import os
import shutil
import ctypes
from datetime import datetime
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable
from urllib.parse import quote


ConflictResolver = Callable[[Path, Path], str]
ProgressCallback = Callable[[int, int, str], None]


def filesystem_path(path: Path) -> str:
    """Return a Windows extended-length path for filesystem API calls."""
    raw = str(Path(path).absolute())
    if os.name != "nt" or raw.startswith("\\\\?\\"):
        return raw
    if raw.startswith("\\\\"):
        return "\\\\?\\UNC\\" + raw[2:]
    return "\\\\?\\" + raw


@dataclass
class OperationFailure:
    source: Path
    target: Path | None
    message: str


@dataclass
class OperationResult:
    completed: list[Path] = field(default_factory=list)
    skipped: list[Path] = field(default_factory=list)
    failures: list[OperationFailure] = field(default_factory=list)

    @property
    def successful(self) -> bool:
        return not self.failures and not self.skipped


def unique_target(target: Path) -> Path:
    if not target.exists():
        return target
    for number in range(2, 10000):
        candidate = target.with_name(f"{target.stem} ({number}){target.suffix}")
        if not candidate.exists():
            return candidate
    raise FileExistsError(f"Cannot find an available name for {target.name}")


def _remove_existing(path: Path) -> None:
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
    else:
        path.unlink()


def _is_junction(path: str) -> bool:
    is_junction = getattr(os.path, "isjunction", None)
    return bool(is_junction and is_junction(path))


def _is_linklike(path: str) -> bool:
    """Treat symlinks and Windows junctions as leaf entries."""
    return os.path.islink(path) or _is_junction(path)


def _copy_or_move(source: Path, target: Path, move: bool) -> None:
    source_path, target_path = filesystem_path(source), filesystem_path(target)
    if move:
        shutil.move(source_path, target_path)
    elif os.path.isdir(source_path):
        shutil.copytree(source_path, target_path)
    else:
        shutil.copy2(source_path, target_path)


def _replace_transactional(source: Path, target: Path, move: bool) -> None:
    backup = unique_target(target.with_name(f".{target.name}.pfc-backup"))
    target.rename(backup)
    try:
        _copy_or_move(source, target, move)
    except (OSError, shutil.Error):
        try:
            if target.exists(): _remove_existing(target)
            backup.rename(target)
        except OSError:
            pass
        raise
    try:
        _remove_existing(backup)
    except OSError:
        pass  # The new item is valid; preserve the old backup rather than risking either copy.


def transfer_items(items: list[Path], destination: Path, move: bool = False,
                   resolve_conflict: ConflictResolver | None = None,
                   continue_on_error: bool = True) -> OperationResult:
    destination.mkdir(parents=True, exist_ok=True)
    result = OperationResult()
    for index, source in enumerate(items):
        target = destination / source.name
        try:
            source_resolved, target_resolved = source.resolve(), target.resolve()
            replace = False
            if source.is_dir() and source_resolved in target_resolved.parents:
                raise OSError("A folder cannot be copied or moved into itself.")
            if target.exists():
                action = resolve_conflict(source, target) if resolve_conflict else "replace"
                if action == "cancel":
                    result.skipped.extend(items[index:])
                    break
                if action == "skip":
                    result.skipped.append(source)
                    continue
                if action == "keep_both":
                    target = unique_target(target)
                elif action == "replace":
                    if source_resolved == target_resolved:
                        raise OSError("Source and destination are the same item. Choose Keep Both or Skip.")
                    replace = True
                else:
                    raise ValueError(f"Unknown conflict action: {action}")
            if replace:
                _replace_transactional(source, target, move)
            else:
                _copy_or_move(source, target, move)
            result.completed.append(source)
        except (OSError, shutil.Error, ValueError) as exc:
            result.failures.append(OperationFailure(source, target, str(exc)))
            if not continue_on_error:
                result.skipped.extend(items[index + 1:])
                break
    return result


def copy_items(items: list[Path], destination: Path,
               resolve_conflict: ConflictResolver | None = None,
               continue_on_error: bool = True) -> OperationResult:
    return transfer_items(items, destination, move=False, resolve_conflict=resolve_conflict,
                          continue_on_error=continue_on_error)


def move_items(items: list[Path], destination: Path,
               resolve_conflict: ConflictResolver | None = None,
               continue_on_error: bool = True) -> OperationResult:
    return transfer_items(items, destination, move=True, resolve_conflict=resolve_conflict,
                          continue_on_error=continue_on_error)


def _count_delete_entries(path: Path) -> int:
    """Count a deletion tree without following links or Windows junctions."""
    filesystem = filesystem_path(path)
    if not os.path.isdir(filesystem) or _is_linklike(filesystem):
        return 1
    total = 1
    with os.scandir(filesystem) as entries:
        for entry in entries:
            child = Path(entry.path)
            if entry.is_dir(follow_symlinks=False):
                total += _count_delete_entries(child)
            else:
                total += 1
    return total


def _remove_with_progress(path: Path, removed: Callable[[Path], None]) -> None:
    """Delete a tree bottom-up and report each removed filesystem entry."""
    filesystem = filesystem_path(path)
    if os.path.isdir(filesystem) and not _is_linklike(filesystem):
        with os.scandir(filesystem) as entries:
            children = [Path(entry.path) for entry in entries]
        for child in children:
            _remove_with_progress(child, removed)
        os.rmdir(filesystem)
    elif _is_junction(filesystem):
        os.rmdir(filesystem)
    else:
        os.unlink(filesystem)
    removed(path)


def delete_items(items: list[Path], continue_on_error: bool = True,
                 progress: ProgressCallback | None = None) -> OperationResult:
    result = OperationResult()
    total = 0
    if progress:
        for item in items:
            progress(0, 0, item.name)
            try:
                total += _count_delete_entries(item)
            except OSError:
                total += 1
        progress(0, total, "")
    completed_entries = 0
    for index, item in enumerate(items):
        try:
            if progress:
                def removed(path: Path) -> None:
                    nonlocal completed_entries
                    completed_entries += 1
                    progress(completed_entries, total, path.name)
                _remove_with_progress(item, removed)
            else:
                _remove_existing(item)
            result.completed.append(item)
        except OSError as exc:
            result.failures.append(OperationFailure(item, None, str(exc)))
            if not continue_on_error:
                result.skipped.extend(items[index + 1:])
                break
    return result


class _SHFILEOPSTRUCTW(ctypes.Structure):
    _fields_ = [("hwnd", ctypes.c_void_p), ("wFunc", ctypes.c_uint),
                ("pFrom", ctypes.c_wchar_p), ("pTo", ctypes.c_wchar_p),
                ("fFlags", ctypes.c_ushort), ("fAnyOperationsAborted", ctypes.c_int),
                ("hNameMappings", ctypes.c_void_p), ("lpszProgressTitle", ctypes.c_wchar_p)]


def recycle_items(items: list[Path], continue_on_error: bool = True,
                  progress: ProgressCallback | None = None) -> OperationResult:
    result = OperationResult()
    if os.name != "nt":
        trash_root = Path.home() / ".local" / "share" / "Trash"
        files_root, info_root = trash_root / "files", trash_root / "info"
        files_root.mkdir(parents=True, exist_ok=True)
        info_root.mkdir(parents=True, exist_ok=True)
        for index, item in enumerate(items):
            target = None
            try:
                if progress:
                    progress(0, 0, item.name)
                original = item.resolve()
                target = unique_target(files_root / item.name)
                shutil.move(str(item), str(target))
                info = info_root / f"{target.name}.trashinfo"
                info.write_text(
                    "[Trash Info]\n"
                    f"Path={quote(str(original), safe='/')}\n"
                    f"DeletionDate={datetime.now():%Y-%m-%dT%H:%M:%S}\n",
                    encoding="utf-8")
                result.completed.append(item)
                if progress:
                    progress(index + 1, len(items), item.name)
            except (OSError, shutil.Error) as exc:
                if target is not None and target.exists() and not item.exists():
                    try:
                        shutil.move(str(target), str(item))
                    except (OSError, shutil.Error):
                        pass
                result.failures.append(OperationFailure(item, None, str(exc)))
                if not continue_on_error:
                    result.skipped.extend(items[index + 1:])
                    break
        return result
    shell32 = ctypes.windll.shell32
    kernel32 = ctypes.windll.kernel32
    kernel32.GetDriveTypeW.argtypes = [ctypes.c_wchar_p]
    kernel32.GetDriveTypeW.restype = ctypes.c_uint
    shell32.SHFileOperationW.argtypes = [ctypes.POINTER(_SHFILEOPSTRUCTW)]
    shell32.SHFileOperationW.restype = ctypes.c_int
    for index, item in enumerate(items):
        if progress:
            progress(0, 0, item.name)
        if str(item).startswith("\\\\") or (item.anchor and kernel32.GetDriveTypeW(str(item.anchor)) == 4):
            result.failures.append(OperationFailure(
                item, None, "Network locations do not provide a safe Windows Recycle Bin. Use Shift+Del explicitly."))
            if not continue_on_error:
                result.skipped.extend(items[index + 1:])
                break
            continue
        operation = _SHFILEOPSTRUCTW(None, 3, str(item.resolve()) + "\0\0", None,
                                     0x40 | 0x10 | 0x04 | 0x400, 0, None, None)
        code = shell32.SHFileOperationW(ctypes.byref(operation))
        if code == 0 and not operation.fAnyOperationsAborted:
            result.completed.append(item)
            if progress:
                progress(index + 1, len(items), item.name)
        else:
            message = "Recycle operation was cancelled." if operation.fAnyOperationsAborted else f"Windows error 0x{code:04X}"
            result.failures.append(OperationFailure(item, None, message))
            if not continue_on_error:
                result.skipped.extend(items[index + 1:])
                break
    return result


def format_size(size: int) -> str:
    value = float(size)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if value < 1024 or unit == "TB":
            return f"{value:.0f} {unit}" if unit == "B" else f"{value:.1f} {unit}"
        value /= 1024
    return str(size)


def compact_file_size(size: int) -> str:
    """File-list size: integer half-up rounding, retaining 1024-based units."""
    divisor = 1
    for unit in ("B", "kB", "MB", "GB", "TB"):
        rounded = (int(size) * 2 + divisor) // (2 * divisor)
        if rounded < 1024 or unit == "TB":
            return f"{rounded} {unit}"
        divisor *= 1024


def roots() -> list[Path]:
    if os.name != "nt":
        return [Path("/")]
    return [Path(f"{letter}:\\") for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" if Path(f"{letter}:\\").exists()]


def is_system(path: Path) -> bool:
    """Return whether Windows marks a path with the SYSTEM attribute."""
    if os.name != "nt":
        return False
    attributes = ctypes.windll.kernel32.GetFileAttributesW(str(path))
    return attributes not in (-1, 0xFFFFFFFF) and bool(attributes & 0x4)


def is_hidden(path: Path) -> bool:
    """Include Windows HIDDEN attributes as well as portable dot-file names."""
    if path.name.startswith('.'):
        return True
    if os.name != 'nt':
        return False
    attributes = ctypes.windll.kernel32.GetFileAttributesW(str(path))
    return attributes not in (-1, 0xffffffff) and bool(attributes & 2)


import ctypes
import os
import shutil
import struct
import time
from dataclasses import dataclass
from pathlib import Path


CF_HDROP = 15
GMEM_MOVEABLE_ZEROINIT = 0x0042
DROPEFFECT_COPY = 1
DROPEFFECT_MOVE = 2
TYMED_HGLOBAL = 1
TYMED_FILE = 2
TYMED_ISTREAM = 4
DVASPECT_CONTENT = 1
_portable_paths: list[Path] = []
_portable_cut = False


@dataclass(frozen=True)
class VirtualFileDescriptor:
    name: str
    size: int


class _FORMATETC(ctypes.Structure):
    _fields_ = [("cfFormat", ctypes.c_ushort), ("ptd", ctypes.c_void_p),
                ("dwAspect", ctypes.c_uint32), ("lindex", ctypes.c_long),
                ("tymed", ctypes.c_uint32)]


class _STGMEDIUM(ctypes.Structure):
    _fields_ = [("tymed", ctypes.c_uint32), ("data", ctypes.c_void_p),
                ("pUnkForRelease", ctypes.c_void_p)]


class _FILEDESCRIPTORW(ctypes.Structure):
    _fields_ = [("dwFlags", ctypes.c_uint32), ("clsid", ctypes.c_byte * 16),
                ("sizel", ctypes.c_long * 2), ("pointl", ctypes.c_long * 2),
                ("dwFileAttributes", ctypes.c_uint32), ("ftCreationTime", ctypes.c_uint32 * 2),
                ("ftLastAccessTime", ctypes.c_uint32 * 2), ("ftLastWriteTime", ctypes.c_uint32 * 2),
                ("nFileSizeHigh", ctypes.c_uint32), ("nFileSizeLow", ctypes.c_uint32),
                ("cFileName", ctypes.c_wchar * 260)]


def _register_clipboard_format(name: str) -> int:
    user32 = ctypes.windll.user32
    user32.RegisterClipboardFormatW.argtypes = [ctypes.c_wchar_p]
    user32.RegisterClipboardFormatW.restype = ctypes.c_uint
    return user32.RegisterClipboardFormatW(name)


def _safe_virtual_name(value: str) -> str:
    name = value.replace("\\", "/").split("/")[-1].strip().rstrip(". ")
    if not name or name in {".", ".."}:
        raise OSError("Outlook supplied an invalid attachment name.")
    return name


def parse_file_group_descriptor(data: bytes) -> list[VirtualFileDescriptor]:
    if len(data) < 4:
        raise OSError("The virtual-file descriptor is incomplete.")
    count = struct.unpack_from("<I", data)[0]
    descriptor_size = ctypes.sizeof(_FILEDESCRIPTORW)
    if count > 10000 or len(data) < 4 + count * descriptor_size:
        raise OSError("The virtual-file descriptor has an invalid item count.")
    result = []
    for index in range(count):
        descriptor = _FILEDESCRIPTORW.from_buffer_copy(data, 4 + index * descriptor_size)
        result.append(VirtualFileDescriptor(_safe_virtual_name(descriptor.cFileName),
                                            (descriptor.nFileSizeHigh << 32) | descriptor.nFileSizeLow))
    return result


def _vtable_method(pointer: int, index: int, result_type, *argument_types):
    table = ctypes.cast(pointer, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
    return ctypes.WINFUNCTYPE(result_type, ctypes.c_void_p, *argument_types)(table[index])


def _release_interface(pointer: int) -> None:
    if pointer:
        _vtable_method(pointer, 2, ctypes.c_ulong)(pointer)


def _get_ole_clipboard():
    ole32 = ctypes.windll.ole32
    ole32.OleInitialize.argtypes = [ctypes.c_void_p]; ole32.OleInitialize.restype = ctypes.c_long
    initialized = ole32.OleInitialize(None)
    if initialized < 0:
        raise OSError(f"Cannot initialize OLE clipboard access (0x{initialized & 0xFFFFFFFF:08X}).")
    pointer = ctypes.c_void_p()
    ole32.OleGetClipboard.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
    ole32.OleGetClipboard.restype = ctypes.c_long
    status = ole32.OleGetClipboard(ctypes.byref(pointer))
    if status < 0 or not pointer.value:
        ole32.OleUninitialize()
        raise OSError("The Windows clipboard does not expose an OLE data object.")
    return pointer.value, initialized in (0, 1)


def _get_medium(data_object: int, format_id: int, index: int, tymed: int) -> _STGMEDIUM:
    request = _FORMATETC(format_id, None, DVASPECT_CONTENT, index, tymed)
    medium = _STGMEDIUM()
    get_data = _vtable_method(data_object, 3, ctypes.c_long,
                              ctypes.POINTER(_FORMATETC), ctypes.POINTER(_STGMEDIUM))
    status = get_data(data_object, ctypes.byref(request), ctypes.byref(medium))
    if status < 0:
        raise OSError(f"Outlook could not render attachment data (0x{status & 0xFFFFFFFF:08X}).")
    return medium


def _release_medium(medium: _STGMEDIUM) -> None:
    ctypes.windll.ole32.ReleaseStgMedium(ctypes.byref(medium))


def _global_bytes(handle: int) -> bytes:
    kernel32 = ctypes.windll.kernel32
    kernel32.GlobalLock.argtypes = [ctypes.c_void_p]; kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalSize.argtypes = [ctypes.c_void_p]; kernel32.GlobalSize.restype = ctypes.c_size_t
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
    pointer, size = kernel32.GlobalLock(handle), kernel32.GlobalSize(handle)
    if not pointer:
        raise OSError("Cannot read virtual-file clipboard memory.")
    try: return ctypes.string_at(pointer, size)
    finally: kernel32.GlobalUnlock(handle)


def _virtual_descriptors_from_object(data_object: int) -> list[VirtualFileDescriptor]:
    format_id = _register_clipboard_format("FileGroupDescriptorW")
    medium = _get_medium(data_object, format_id, -1, TYMED_HGLOBAL)
    try:
        if medium.tymed != TYMED_HGLOBAL or not medium.data:
            raise OSError("Outlook returned an unsupported attachment descriptor medium.")
        return parse_file_group_descriptor(_global_bytes(medium.data))
    finally:
        _release_medium(medium)


def data_object_has_format(data_object: int, format_id: int, index: int = -1,
                           tymed: int = TYMED_HGLOBAL) -> bool:
    """Return whether an OLE IDataObject can render the requested format."""
    request = _FORMATETC(format_id, None, DVASPECT_CONTENT, index, tymed)
    query = _vtable_method(data_object, 5, ctypes.c_long, ctypes.POINTER(_FORMATETC))
    return query(data_object, ctypes.byref(request)) >= 0


def virtual_file_format_id() -> int:
    return _register_clipboard_format("FileGroupDescriptorW")


def get_virtual_file_descriptors() -> list[VirtualFileDescriptor]:
    if os.name != "nt":
        return []
    data_object = None; uninitialize = False
    try:
        data_object, uninitialize = _get_ole_clipboard()
        return _virtual_descriptors_from_object(data_object)
    except OSError:
        return []
    finally:
        if data_object: _release_interface(data_object)
        if uninitialize: ctypes.windll.ole32.OleUninitialize()


def _write_stream(stream_pointer: int, target: Path) -> None:
    seek = _vtable_method(stream_pointer, 5, ctypes.c_long, ctypes.c_longlong,
                          ctypes.c_uint32, ctypes.POINTER(ctypes.c_ulonglong))
    position = ctypes.c_ulonglong()
    seek(stream_pointer, 0, 0, ctypes.byref(position))
    read = _vtable_method(stream_pointer, 3, ctypes.c_long, ctypes.c_void_p,
                          ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong))
    buffer = ctypes.create_string_buffer(1024 * 1024)
    with target.open("wb") as output:
        while True:
            count = ctypes.c_ulong()
            status = read(stream_pointer, buffer, len(buffer), ctypes.byref(count))
            if status < 0:
                raise OSError(f"Cannot read Outlook attachment stream (0x{status & 0xFFFFFFFF:08X}).")
            if count.value:
                output.write(buffer.raw[:count.value])
            if count.value == 0 or status == 1:
                break


def _write_virtual_medium(medium: _STGMEDIUM, target: Path, expected_size: int) -> None:
    if medium.tymed == TYMED_ISTREAM and medium.data:
        _write_stream(medium.data, target)
    elif medium.tymed == TYMED_HGLOBAL and medium.data:
        data = _global_bytes(medium.data)
        target.write_bytes(data[:expected_size] if expected_size else data)
    elif medium.tymed == TYMED_FILE and medium.data:
        shutil.copy2(ctypes.wstring_at(medium.data), target)
    else:
        raise OSError(f"Unsupported Outlook attachment medium: {medium.tymed}")


def extract_virtual_files_from_data_object(
        data_object: int, destination: Path) -> tuple[list[Path], list[tuple[str, str]]]:
    """Materialize Outlook/Teams virtual files while IDataObject is still valid."""
    extracted, failures = [], []
    destination.mkdir(parents=True, exist_ok=True)
    descriptors = _virtual_descriptors_from_object(data_object)
    content_format = _register_clipboard_format("FileContents")
    for index, descriptor in enumerate(descriptors):
        target = destination / descriptor.name
        if target.exists():
            target = target.with_name(f"{target.stem} ({index + 2}){target.suffix}")
        medium = None
        try:
            medium = _get_medium(data_object, content_format, index,
                                 TYMED_ISTREAM | TYMED_HGLOBAL | TYMED_FILE)
            _write_virtual_medium(medium, target, descriptor.size)
            extracted.append(target)
        except OSError as exc:
            failures.append((descriptor.name, str(exc)))
            try: target.unlink(missing_ok=True)
            except OSError: pass
        finally:
            if medium is not None: _release_medium(medium)
    return extracted, failures


def extract_virtual_files(destination: Path) -> tuple[list[Path], list[tuple[str, str]]]:
    if os.name != "nt":
        return [], []
    data_object = None; uninitialize = False
    try:
        data_object, uninitialize = _get_ole_clipboard()
        return extract_virtual_files_from_data_object(data_object, destination)
    finally:
        if data_object: _release_interface(data_object)
        if uninitialize: ctypes.windll.ole32.OleUninitialize()


def _open_clipboard() -> None:
    user32 = ctypes.windll.user32
    for _ in range(10):
        if user32.OpenClipboard(None):
            return
        time.sleep(0.02)
    raise OSError("The Windows clipboard is busy.")


def _global_data(payload: bytes) -> int:
    kernel32 = ctypes.windll.kernel32
    kernel32.GlobalAlloc.restype = ctypes.c_void_p
    kernel32.GlobalAlloc.argtypes = [ctypes.c_uint, ctypes.c_size_t]
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
    kernel32.GlobalFree.argtypes = [ctypes.c_void_p]
    handle = kernel32.GlobalAlloc(GMEM_MOVEABLE_ZEROINIT, len(payload))
    if not handle:
        raise MemoryError("Cannot allocate clipboard memory.")
    pointer = kernel32.GlobalLock(handle)
    if not pointer:
        kernel32.GlobalFree(handle)
        raise MemoryError("Cannot lock clipboard memory.")
    ctypes.memmove(pointer, payload, len(payload))
    kernel32.GlobalUnlock(handle)
    return handle


def set_file_clipboard(paths: list[Path], cut: bool = False) -> None:
    """Publish files in the same clipboard formats used by File Explorer."""
    if os.name != "nt":
        global _portable_paths, _portable_cut
        _portable_paths = [path.resolve() for path in paths]
        _portable_cut = cut
        return
    resolved = [str(path.resolve()) for path in paths]
    if not resolved:
        return
    dropfiles = struct.pack("<IiiII", 20, 0, 0, 0, 1)
    dropfiles += ("\0".join(resolved) + "\0\0").encode("utf-16le")
    drop_handle = _global_data(dropfiles)
    effect_handle = _global_data(struct.pack("<I", DROPEFFECT_MOVE if cut else DROPEFFECT_COPY))
    user32 = ctypes.windll.user32
    user32.SetClipboardData.restype = ctypes.c_void_p
    user32.SetClipboardData.argtypes = [ctypes.c_uint, ctypes.c_void_p]
    effect_format = _register_clipboard_format("Preferred DropEffect")
    _open_clipboard()
    try:
        if not user32.EmptyClipboard():
            raise OSError("Cannot clear the Windows clipboard.")
        if not user32.SetClipboardData(CF_HDROP, drop_handle):
            raise OSError("Cannot place files on the Windows clipboard.")
        drop_handle = None  # Windows owns successful clipboard handles.
        if not user32.SetClipboardData(effect_format, effect_handle):
            raise OSError("Cannot set the clipboard copy/cut mode.")
        effect_handle = None
    finally:
        user32.CloseClipboard()
        if drop_handle:
            ctypes.windll.kernel32.GlobalFree(drop_handle)
        if effect_handle:
            ctypes.windll.kernel32.GlobalFree(effect_handle)


def get_file_clipboard() -> tuple[list[Path], bool]:
    """Read files copied or cut by PFC or Windows File Explorer."""
    if os.name != "nt":
        return list(_portable_paths), _portable_cut
    user32, shell32, kernel32 = ctypes.windll.user32, ctypes.windll.shell32, ctypes.windll.kernel32
    user32.GetClipboardData.restype = ctypes.c_void_p
    user32.GetClipboardData.argtypes = [ctypes.c_uint]
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
    shell32.DragQueryFileW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_wchar_p, ctypes.c_uint]
    effect_format = _register_clipboard_format("Preferred DropEffect")
    _open_clipboard()
    try:
        drop_handle = user32.GetClipboardData(CF_HDROP)
        if not drop_handle:
            return [], False
        count = shell32.DragQueryFileW(drop_handle, 0xFFFFFFFF, None, 0)
        paths = []
        for index in range(count):
            length = shell32.DragQueryFileW(drop_handle, index, None, 0)
            buffer = ctypes.create_unicode_buffer(length + 1)
            shell32.DragQueryFileW(drop_handle, index, buffer, length + 1)
            paths.append(Path(buffer.value))
        cut = False
        effect_handle = user32.GetClipboardData(effect_format)
        if effect_handle:
            pointer = kernel32.GlobalLock(effect_handle)
            if pointer:
                cut = ctypes.c_uint32.from_address(pointer).value == DROPEFFECT_MOVE
                kernel32.GlobalUnlock(effect_handle)
        return paths, cut
    finally:
        user32.CloseClipboard()


def clear_file_clipboard() -> None:
    if os.name != "nt":
        global _portable_paths, _portable_cut
        _portable_paths = []
        _portable_cut = False
        return
    _open_clipboard()
    try:
        ctypes.windll.user32.EmptyClipboard()
    finally:
        ctypes.windll.user32.CloseClipboard()


import base64
import binascii
import ctypes
import os
import struct
import zlib
from collections import OrderedDict
from pathlib import Path
from tkinter import PhotoImage


VCS_BADGE_SPECS = {
    "clean": ("#218838", "check", "#ffffff"),
    "modified": ("#e02f2f", "alert", "#ffffff"),
    "added": ("#1266b3", "plus", "#ffffff"),
    "untracked": ("#582a9b", "question", "#ffffff"),
    "deleted": ("#a80f20", "minus", "#ffffff"),
    "conflict": ("#f2b705", "cross", "#171717"),
}

FILE_ATTRIBUTE_NORMAL = 0x80
SHGFI_ICON = 0x100
SHGFI_SMALLICON = 0x1
SHGFI_USEFILEATTRIBUTES = 0x10
HGDI_ERROR = ctypes.c_void_p(-1).value


class _SHFILEINFO(ctypes.Structure):
    _fields_ = [("hIcon", ctypes.c_void_p), ("iIcon", ctypes.c_int),
                ("dwAttributes", ctypes.c_uint32), ("szDisplayName", ctypes.c_wchar * 260),
                ("szTypeName", ctypes.c_wchar * 80)]


class _BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [("biSize", ctypes.c_uint32), ("biWidth", ctypes.c_long),
                ("biHeight", ctypes.c_long), ("biPlanes", ctypes.c_ushort),
                ("biBitCount", ctypes.c_ushort), ("biCompression", ctypes.c_uint32),
                ("biSizeImage", ctypes.c_uint32), ("biXPelsPerMeter", ctypes.c_long),
                ("biYPelsPerMeter", ctypes.c_long), ("biClrUsed", ctypes.c_uint32),
                ("biClrImportant", ctypes.c_uint32)]


class _BITMAPINFO(ctypes.Structure):
    _fields_ = [("bmiHeader", _BITMAPINFOHEADER), ("bmiColors", ctypes.c_uint32 * 3)]


def _chunk(kind: bytes, data: bytes) -> bytes:
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", binascii.crc32(kind + data) & 0xFFFFFFFF)


def _png_from_bgra(raw: bytes, size: int) -> bytes:
    rgba = bytearray()
    has_alpha = any(raw[index + 3] for index in range(0, len(raw), 4))
    for row in range(size):
        rgba.append(0)
        for column in range(size):
            index = (row * size + column) * 4
            blue, green, red, alpha = raw[index:index + 4]
            if not has_alpha:
                alpha = 255 if red or green or blue else 0
            rgba.extend((red, green, blue, alpha))
    header = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", header) + _chunk(b"IDAT", zlib.compress(bytes(rgba), 9)) + _chunk(b"IEND", b"")


def _shell_icon_request(path: Path, is_dir: bool) -> tuple[str, int, int]:
    """Build a Shell icon request without parsing untrusted executable resources."""
    flags = SHGFI_ICON | SHGFI_SMALLICON
    if not is_dir and path.suffix.casefold() == ".exe":
        return ".exe", FILE_ATTRIBUTE_NORMAL, flags | SHGFI_USEFILEATTRIBUTES
    return str(path), 0, flags


def _inside_polygon(x: float, y: float, points) -> bool:
    inside = False
    previous = points[-1]
    for current in points:
        x1, y1 = previous; x2, y2 = current
        if (y1 > y) != (y2 > y):
            crossing = (x2 - x1) * (y - y1) / (y2 - y1) + x1
            if x < crossing:
                inside = not inside
        previous = current
    return inside


def _paint_polygon(pixels: bytearray, canvas_size: int, points, color) -> None:
    left = max(0, int(min(x for x, _y in points)))
    right = min(canvas_size - 1, int(max(x for x, _y in points)) + 1)
    top = max(0, int(min(y for _x, y in points)))
    bottom = min(canvas_size - 1, int(max(y for _x, y in points)) + 1)
    for row in range(top, bottom + 1):
        for column in range(left, right + 1):
            if _inside_polygon(column + 0.5, row + 0.5, points):
                index = (row * canvas_size + column) * 4
                pixels[index:index + 4] = bytes(color)


def pfc_icon_png(size: int = 32) -> bytes:
    """Render a red/black interlocking-arrow mark with a light taskbar outline."""
    if size < 8:
        raise ValueError("PFC icon size must be at least 8 pixels")
    supersample = 4
    canvas_size = size * supersample
    factor = canvas_size / 64
    shape = bytearray(canvas_size * canvas_size * 4)
    red, black = (238, 28, 45, 255), (25, 24, 27, 255)
    left_half = ((19, 3), (32, 16), (32, 30), (19, 18))
    right_half = ((45, 3), (32, 16), (32, 30), (45, 18))

    def rotate(points):
        return tuple((64 - y, x) for x, y in points)

    left, right = left_half, right_half
    for index in range(4):
        left_color, right_color = ((black, red) if index % 2 == 0 else
                                   (red, black))
        _paint_polygon(shape, canvas_size,
                       tuple((x * factor, y * factor) for x, y in left),
                       left_color)
        _paint_polygon(shape, canvas_size,
                       tuple((x * factor, y * factor) for x, y in right),
                       right_color)
        left, right = rotate(left), rotate(right)

    # The open center keeps the four inward arrows visually separate.
    center = ((32, 25), (39, 32), (32, 39), (25, 32))
    _paint_polygon(shape, canvas_size,
                   tuple((x * factor, y * factor) for x, y in center),
                   (0, 0, 0, 0))

    # A narrow white silhouette keeps the black vanes visible on dark Aero/taskbars.
    pixels = bytearray(canvas_size * canvas_size * 4)
    radius = max(2, round(1.35 * factor))
    for row in range(canvas_size):
        for column in range(canvas_size):
            index = (row * canvas_size + column) * 4
            if shape[index + 3]:
                continue
            found = False
            for offset_y in range(-radius, radius + 1):
                check_y = row + offset_y
                if not 0 <= check_y < canvas_size:
                    continue
                for offset_x in range(-radius, radius + 1):
                    if offset_x * offset_x + offset_y * offset_y > radius * radius:
                        continue
                    check_x = column + offset_x
                    if not 0 <= check_x < canvas_size:
                        continue
                    check = (check_y * canvas_size + check_x) * 4
                    if shape[check + 3]:
                        found = True; break
                if found:
                    break
            if found:
                pixels[index:index + 4] = bytes((255, 255, 255, 255))
    for index in range(0, len(shape), 4):
        if shape[index + 3]:
            pixels[index:index + 4] = shape[index:index + 4]

    rgba = bytearray()
    for row in range(size):
        rgba.append(0)
        for column in range(size):
            samples = []
            for sub_y in range(supersample):
                for sub_x in range(supersample):
                    index = (((row * supersample + sub_y) * canvas_size +
                              column * supersample + sub_x) * 4)
                    samples.append(pixels[index:index + 4])
            alpha_sum = sum(sample[3] for sample in samples)
            alpha = round(alpha_sum / len(samples))
            if alpha_sum:
                red = round(sum(sample[0] * sample[3] for sample in samples) / alpha_sum)
                green = round(sum(sample[1] * sample[3] for sample in samples) / alpha_sum)
                blue = round(sum(sample[2] * sample[3] for sample in samples) / alpha_sum)
            else:
                red = green = blue = 0
            rgba.extend((red, green, blue, alpha))
    header = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", header) +
            _chunk(b"IDAT", zlib.compress(bytes(rgba), 9)) + _chunk(b"IEND", b""))


def create_pfc_icon(size: int = 32) -> PhotoImage:
    encoded = base64.b64encode(pfc_icon_png(size)).decode("ascii")
    return PhotoImage(data=encoded, format="png")


def pfc_icon_ico(size: int = 32) -> bytes:
    """Wrap the PNG app badge in a Windows ICO container for Shell_NotifyIcon."""
    png = pfc_icon_png(size)
    width = 0 if size >= 256 else size
    entry = struct.pack("<BBBBHHII", width, width, 0, 0, 1, 32, len(png), 22)
    return struct.pack("<HHH", 0, 1, 1) + entry + png


def _rgba_png_downsample(pixels: bytearray, output_size: int, supersample: int) -> bytes:
    canvas_size = output_size * supersample
    rgba = bytearray()
    for row in range(output_size):
        rgba.append(0)
        for column in range(output_size):
            samples = []
            for sub_y in range(supersample):
                for sub_x in range(supersample):
                    index = (((row * supersample + sub_y) * canvas_size +
                              column * supersample + sub_x) * 4)
                    samples.append(pixels[index:index + 4])
            alpha_sum = sum(sample[3] for sample in samples)
            alpha = round(alpha_sum / len(samples))
            if alpha_sum:
                colors = [round(sum(sample[channel] * sample[3] for sample in samples) / alpha_sum)
                          for channel in range(3)]
            else:
                colors = [0, 0, 0]
            rgba.extend((*colors, alpha))
    header = struct.pack(">IIBBBBB", output_size, output_size, 8, 6, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", header) +
            _chunk(b"IDAT", zlib.compress(bytes(rgba), 9)) + _chunk(b"IEND", b""))


def _hex_rgba(value: str) -> tuple[int, int, int, int]:
    value = value.lstrip("#")
    return tuple(int(value[index:index + 2], 16) for index in (0, 2, 4)) + (255,)


def _distance_to_segment(px, py, x1, y1, x2, y2) -> float:
    dx, dy = x2 - x1, y2 - y1
    if dx == dy == 0:
        return ((px - x1) ** 2 + (py - y1) ** 2) ** .5
    position = max(0.0, min(1.0, ((px - x1) * dx + (py - y1) * dy) /
                                (dx * dx + dy * dy)))
    nearest_x, nearest_y = x1 + position * dx, y1 + position * dy
    return ((px - nearest_x) ** 2 + (py - nearest_y) ** 2) ** .5


def vcs_badge_png(size: int, status: str) -> bytes:
    """Render one anti-aliased Git/SVN badge with a solid status-color face."""
    if size < 8 or status not in VCS_BADGE_SPECS:
        raise ValueError("Unsupported VCS badge")
    fill, glyph, ink = VCS_BADGE_SPECS[status]
    supersample, canvas_size = 6, size * 6
    pixels = bytearray(canvas_size * canvas_size * 4)
    center = (canvas_size - 1) / 2
    outer = canvas_size / 2 - .5
    dark_edge = _hex_rgba("#17212b")
    fill_rgba, ink_rgba = _hex_rgba(fill), _hex_rgba(ink)
    dark_width = max(5, round(canvas_size * .105))
    for y in range(canvas_size):
        for x in range(canvas_size):
            distance = ((x - center) ** 2 + (y - center) ** 2) ** .5
            color = (dark_edge if distance <= outer else None)
            if distance <= outer - dark_width:
                color = fill_rgba
            if color:
                index = (y * canvas_size + x) * 4
                pixels[index:index + 4] = bytes(color)

    def point(x, y):
        return x * (canvas_size - 1), y * (canvas_size - 1)

    segments, dots = [], []
    if glyph == "check":
        segments = [((*point(.24, .52), *point(.42, .68))),
                    ((*point(.42, .68), *point(.76, .31)))]
    elif glyph == "alert":
        segments = [((*point(.50, .23), *point(.50, .51)))]
        dots = [point(.50, .72)]
    elif glyph == "plus":
        segments = [((*point(.50, .28), *point(.50, .72))),
                    ((*point(.28, .50), *point(.72, .50)))]
    elif glyph == "minus":
        segments = [((*point(.28, .50), *point(.72, .50)))]
    elif glyph == "cross":
        segments = [((*point(.29, .29), *point(.71, .71))),
                    ((*point(.71, .29), *point(.29, .71)))]
    elif glyph == "question":
        segments = [((*point(.32, .34), *point(.40, .28))),
                    ((*point(.40, .28), *point(.59, .28))),
                    ((*point(.59, .28), *point(.67, .36))),
                    ((*point(.67, .36), *point(.63, .44))),
                    ((*point(.63, .44), *point(.51, .51))),
                    ((*point(.51, .51), *point(.50, .56)))]
        dots = [point(.50, .72)]
    line_radius = max(3, round(canvas_size * .055))
    dot_radius = max(3, round(canvas_size * .055))
    for y in range(canvas_size):
        for x in range(canvas_size):
            sample_x, sample_y = x + .5, y + .5
            painted = any(_distance_to_segment(sample_x, sample_y, *segment) <= line_radius
                          for segment in segments)
            painted = painted or any(((sample_x - dot_x) ** 2 + (sample_y - dot_y) ** 2) ** .5
                                     <= dot_radius for dot_x, dot_y in dots)
            if painted:
                index = (y * canvas_size + x) * 4
                pixels[index:index + 4] = bytes(ink_rgba)
    return _rgba_png_downsample(pixels, size, supersample)


def cloud_badge_png(size: int, status: str) -> bytes:
    """Square OneDrive badges: separate shape/location from round Git badges."""
    colors = {'online': '#0078d4', 'available': '#16853c', 'pinned': '#16853c',
              'syncing': '#0078d4', 'error': '#da2020', 'paused': '#b56b00', 'warning': '#b56b00'}
    if status not in colors or size < 8:
        raise ValueError('Unsupported cloud badge')
    factor = 6
    side = size * factor
    pixels = bytearray(side * side * 4)
    outline = status in ('online', 'available')
    face, ink = ((_hex_rgba('#ffffff'), _hex_rgba(colors[status])) if outline else
                 (_hex_rgba(colors[status]), _hex_rgba('#ffffff')))
    segments = []
    if status in ('available', 'pinned'):
        segments = [(0.2,0.50,0.43,0.73),(0.43,0.73,0.80,0.25)]
    elif status == 'syncing':
        segments = [(0.22,0.32,0.78,0.32),(0.78,0.32,0.62,0.18),
                    (0.78,0.32,0.62,0.46),(0.78,0.69,0.22,0.69),
                    (0.22,0.69,0.38,0.55),(0.22,0.69,0.38,0.83)]
    elif status == 'paused':
        segments = [(0.35,0.25,0.35,0.75),(0.65,0.25,0.65,0.75)]
    elif status == 'error':
        segments = [(0.28,0.28,0.72,0.72),(0.72,0.28,0.28,0.72)]
    elif status == 'warning':
        segments = [(0.5,0.2,0.5,0.55),(0.5,0.75,0.5,0.76)]
    for y in range(side):
        for x in range(side):
            nx, ny = (x+.5)/side, (y+.5)/side
            if not (.025 < nx < .975 and .025 < ny < .975):
                continue
            color = face
            if min(nx, ny, 1-nx, 1-ny) < .08:
                color = _hex_rgba(colors[status])
            painted = any(_distance_to_segment(nx, ny, *line) < .05 for line in segments)
            if status == 'online':
                painted = ((nx-.40)**2+(ny-.46)**2 < .18**2 or
                           (nx-.61)**2+(ny-.53)**2 < .18**2 or
                           (.23 < nx < .77 and .49 < ny < .69))
            if painted:
                color = ink
            pos = (y*side+x)*4
            pixels[pos:pos+4] = bytes(color)
    return _rgba_png_downsample(pixels, size, factor)


def folder_nav_icon_png(kind: str, size: int) -> bytes:
    """Small, antialiased navigation glyphs; no Shell calls or disk access."""
    scale, extent = size*4/24, size*4
    pixels = bytearray(extent*extent*4)
    def polygon(points, color):
        _paint_polygon(pixels, extent, [(x*scale, y*scale) for x,y in points], _hex_rgba(color))
    def box(x1,y1,x2,y2,color):
        polygon(((x1,y1),(x2,y1),(x2,y2),(x1,y2)),color)
    if kind == 'pc':
        box(2,3,22,17,'#6d8294'); box(3,4,21,16,'#c5dbe9')
        box(4,5,20,14,'#6fa3c4'); box(5,6,19,8,'#a3cce4')
        box(10,17,14,20,'#8497a3'); box(6,20,18,21,'#657b8a')
    elif kind == 'drive':
        polygon(((4,7),(20,7),(22,15),(22,20),(2,20),(2,15)), '#768894')
        polygon(((5,8),(19,8),(21,15),(3,15)), '#dce5eb')
        box(3,16,21,19,'#b6c4ce'); box(5,17,13,18,'#7d919f')
        box(18,17,20,18,'#178267')
    else:
        polygon(((2,5),(9,5),(11,7),(21,7),(22,9),(22,20),(2,20)), '#bc8c26')
        polygon(((3,6),(9,6),(11,8),(21,8),(21,19),(3,19)), '#f2cd69')
        polygon(((2,10),(22,10),(21,20),(3,20)), '#d8a43c')
        polygon(((3,11),(21,11),(20,19),(4,19)), '#f6d577')
        box(4,11,20,12,'#ffe9a2')
    return _rgba_png_downsample(pixels, size, 4)


class ShellIconProvider:
    """Bounded native icon cache. Widgets must retain images while displaying them."""

    def __init__(self, size: int = 16, text_gap: int | None = None,
                 *, cache_limit: int = 512) -> None:
        self.size = size
        self.text_gap = max(4, round(size * 0.3)) if text_gap is None else text_gap
        self.cache_limit = max(1, cache_limit)
        self.cache: OrderedDict[tuple, PhotoImage] = OrderedDict()
        self.blank = PhotoImage(width=size + self.text_gap, height=size)

    def get(self, path: Path, is_dir: bool, overlay: str | None = None, cloud: str | None = None) -> PhotoImage:
        if os.name != "nt":
            return self.blank
        suffix = path.suffix.casefold()
        # Shell folders may carry a Known Folder or desktop.ini icon. Sharing
        # one '<folder>' entry makes the first folder (often Downloads) poison
        # every later directory, including after a zoom recreates this cache.
        # Normalize lexically only: never resolve cloud files, links or shares.
        if is_dir or suffix in {".lnk", ".ico"}:
            base_key = ('folder' if is_dir else 'path', os.path.abspath(path))
        else:
            base_key = ('type', suffix)
        key = (base_key, overlay or '', cloud or '')
        if key not in self.cache:
            icon = self._load(path, is_dir)
            if icon is not None and overlay:
                icon = self._with_overlay(icon, overlay, compact=bool(cloud))
            if icon is not None and cloud:
                result = PhotoImage(width=self.size, height=self.size)
                result.tk.call(str(result), 'copy', str(icon), '-to', 0, 0)
                diameter = min(self.size, max(8, round(self.size * .55)))
                badge = PhotoImage(data=base64.b64encode(cloud_badge_png(diameter, cloud)).decode('ascii'), format='png')
                result.tk.call(str(result), 'copy', str(badge), '-to', 0, 0, '-compositingrule', 'overlay')
                icon = result
            self.cache[key] = self._with_text_gap(icon) if icon is not None else self.blank
        self.cache.move_to_end(key)
        while len(self.cache) > self.cache_limit:
            self.cache.popitem(last=False)
        return self.cache[key]

    def _with_overlay(self, icon: PhotoImage, overlay: str, compact=False) -> PhotoImage:
        result = PhotoImage(width=self.size, height=self.size)
        result.tk.call(str(result), "copy", str(icon), "-to", 0, 0)
        if overlay in VCS_BADGE_SPECS:
            diameter = min(self.size, max(8 if compact else 12, round(self.size * (.50 if compact else .70))))
            encoded = base64.b64encode(vcs_badge_png(diameter, overlay)).decode("ascii")
            badge = PhotoImage(data=encoded, format="png")
            result.tk.call(str(result), "copy", str(badge),
                           "-to", self.size - diameter, self.size - diameter,
                           "-compositingrule", "overlay")
        return result

    def _with_text_gap(self, icon: PhotoImage) -> PhotoImage:
        padded = PhotoImage(width=self.size + self.text_gap, height=self.size)
        padded.tk.call(str(padded), "copy", str(icon), "-to", 0, 0)
        return padded

    def _load(self, path: Path, is_dir: bool) -> PhotoImage | None:
        shell32, user32, gdi32 = ctypes.windll.shell32, ctypes.windll.user32, ctypes.windll.gdi32
        shell32.SHGetFileInfoW.restype = ctypes.c_size_t
        shell32.SHGetFileInfoW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32, ctypes.POINTER(_SHFILEINFO), ctypes.c_uint, ctypes.c_uint]
        user32.GetDC.restype = ctypes.c_void_p
        user32.GetDC.argtypes = [ctypes.c_void_p]
        user32.ReleaseDC.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        user32.DestroyIcon.argtypes = [ctypes.c_void_p]
        user32.DrawIconEx.restype = ctypes.c_int
        user32.DrawIconEx.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_void_p,
                                      ctypes.c_int, ctypes.c_int, ctypes.c_uint, ctypes.c_void_p, ctypes.c_uint]
        gdi32.CreateCompatibleDC.restype = ctypes.c_void_p
        gdi32.CreateCompatibleDC.argtypes = [ctypes.c_void_p]
        gdi32.CreateDIBSection.restype = ctypes.c_void_p
        gdi32.CreateDIBSection.argtypes = [ctypes.c_void_p, ctypes.POINTER(_BITMAPINFO), ctypes.c_uint,
                                           ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.c_uint]
        gdi32.SelectObject.restype = ctypes.c_void_p
        gdi32.SelectObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        gdi32.DeleteObject.argtypes = [ctypes.c_void_p]
        gdi32.DeleteDC.argtypes = [ctypes.c_void_p]
        info = _SHFILEINFO()
        # The small Shell handle reliably contains alpha on all supported Windows
        # versions. DrawIconEx scales it to the selected UI profile; some large
        # handles render fully transparent when converted through a 32-bit DIB.
        lookup, attributes, flags = _shell_icon_request(path, is_dir)
        if not shell32.SHGetFileInfoW(
                lookup, attributes, ctypes.byref(info), ctypes.sizeof(info), flags):
            return None
        if not info.hIcon:
            return None
        screen = memory = bitmap = old = None
        raw = None
        try:
            screen = user32.GetDC(None)
            if not screen:
                return None
            memory = gdi32.CreateCompatibleDC(screen)
            if not memory:
                return None
            bitmap_info = _BITMAPINFO()
            bitmap_info.bmiHeader.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
            bitmap_info.bmiHeader.biWidth = self.size
            bitmap_info.bmiHeader.biHeight = -self.size
            bitmap_info.bmiHeader.biPlanes = 1
            bitmap_info.bmiHeader.biBitCount = 32
            bitmap_info.bmiHeader.biCompression = 0
            bits = ctypes.c_void_p()
            bitmap = gdi32.CreateDIBSection(
                memory, ctypes.byref(bitmap_info), 0, ctypes.byref(bits), None, 0)
            if not bitmap or not bits.value:
                return None
            old = gdi32.SelectObject(memory, bitmap)
            if not old or old == HGDI_ERROR:
                old = None
                return None
            ctypes.memset(bits.value, 0, self.size * self.size * 4)
            if not user32.DrawIconEx(
                    memory, 0, 0, info.hIcon, self.size, self.size, 0, None, 0x3):
                return None
            raw = ctypes.string_at(bits.value, self.size * self.size * 4)
        finally:
            if old and memory:
                gdi32.SelectObject(memory, old)
            if bitmap:
                gdi32.DeleteObject(bitmap)
            if memory:
                gdi32.DeleteDC(memory)
            if screen:
                user32.ReleaseDC(None, screen)
            user32.DestroyIcon(info.hIcon)
        if raw is None:
            return None
        try:
            encoded = base64.b64encode(_png_from_bgra(raw, self.size)).decode("ascii")
            return PhotoImage(data=encoded, format="png")
        except Exception:
            return None


import ctypes
import os
import queue
import subprocess
import sys
import tempfile
import threading
from pathlib import Path, PureWindowsPath


AUTOSTART_KEY = r"Software\Microsoft\Windows\CurrentVersion\Run"
AUTOSTART_VALUE = "Python File Commander"


def startup_command(executable: Path | str | None = None,
                    script: Path | str | None = None,
                    *, frozen: bool | None = None,
                    pythonw_exists=None) -> str:
    """Return the per-user Windows startup command for this PFC edition."""
    def resolved(value):
        raw = os.fspath(value)
        windows_path = PureWindowsPath(raw)
        return windows_path if windows_path.drive else Path(raw).resolve()

    executable = resolved(executable or sys.executable)
    frozen = bool(getattr(sys, "frozen", False)) if frozen is None else frozen
    if frozen:
        arguments = [str(executable), "--startup"]
    else:
        candidate = executable.with_name("pythonw.exe")
        exists = Path(candidate).is_file() if pythonw_exists is None else pythonw_exists(candidate)
        launcher = candidate if exists else executable
        script = resolved(script or sys.argv[0])
        arguments = [str(launcher), str(script), "--startup"]
    return subprocess.list2cmdline(arguments)


def set_windows_autostart(enabled: bool, command: str | None = None,
                          registry=None) -> bool:
    """Synchronize PFC's HKCU Run value. Return False off Windows."""
    if registry is None:
        if os.name != "nt":
            return False
        import winreg as registry
    if enabled:
        with registry.CreateKey(registry.HKEY_CURRENT_USER, AUTOSTART_KEY) as key:
            registry.SetValueEx(key, AUTOSTART_VALUE, 0, registry.REG_SZ,
                                command or startup_command())
    else:
        try:
            with registry.OpenKey(registry.HKEY_CURRENT_USER, AUTOSTART_KEY, 0,
                                  registry.KEY_SET_VALUE) as key:
                registry.DeleteValue(key, AUTOSTART_VALUE)
        except FileNotFoundError:
            pass
    return True


class WindowsTrayIcon:
    """Small native notification-area host that sends actions to Tk via a queue."""

    def __init__(self, actions: queue.Queue, icon_bytes: bytes, *,
                 open_label: str, auto_start_label: str, exit_label: str,
                 auto_start_enabled: bool) -> None:
        self.actions = actions
        self.icon_bytes = icon_bytes
        self.open_label = open_label
        self.auto_start_label = auto_start_label
        self.exit_label = exit_label
        self.auto_start_enabled = auto_start_enabled
        self._thread: threading.Thread | None = None
        self._thread_id = 0
        self._hwnd = 0
        self._stop_requested = threading.Event()
        self.error: Exception | None = None

    def start(self) -> bool:
        if os.name != "nt" or self._thread is not None:
            return False
        self._thread = threading.Thread(target=self._run, name="PFC-Tray", daemon=True)
        self._thread.start()
        return True

    def update(self, *, auto_start_enabled: bool | None = None,
               open_label: str | None = None, auto_start_label: str | None = None,
               exit_label: str | None = None) -> None:
        if auto_start_enabled is not None:
            self.auto_start_enabled = auto_start_enabled
        if open_label is not None:
            self.open_label = open_label
        if auto_start_label is not None:
            self.auto_start_label = auto_start_label
        if exit_label is not None:
            self.exit_label = exit_label

    def stop(self) -> None:
        self._stop_requested.set()
        if os.name == "nt" and self._hwnd:
            ctypes.windll.user32.PostMessageW(self._hwnd, 0x0010, 0, 0)  # WM_CLOSE

    def _run(self) -> None:
        from ctypes import wintypes

        WM_APP, WM_CLOSE, WM_DESTROY = 0x8000, 0x0010, 0x0002
        WM_LBUTTONUP, WM_LBUTTONDBLCLK, WM_RBUTTONUP = 0x0202, 0x0203, 0x0205
        WM_NULL, NIM_ADD, NIM_DELETE, NIM_SETVERSION = 0x0000, 0, 2, 4
        NIF_MESSAGE, NIF_ICON, NIF_TIP, NOTIFYICON_VERSION_4 = 1, 2, 4, 4
        MF_STRING, MF_SEPARATOR, MF_CHECKED = 0, 0x0800, 0x0008
        TPM_RIGHTBUTTON, TPM_RETURNCMD = 0x0002, 0x0100
        IMAGE_ICON, LR_LOADFROMFILE = 1, 0x0010
        CALLBACK_MESSAGE = WM_APP + 23
        OPEN_COMMAND, AUTOSTART_COMMAND, EXIT_COMMAND = 1001, 1002, 1003

        class GUID(ctypes.Structure):
            _fields_ = [("Data1", wintypes.DWORD), ("Data2", wintypes.WORD),
                        ("Data3", wintypes.WORD), ("Data4", ctypes.c_ubyte * 8)]

        class NOTIFYICONDATAW(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("hWnd", wintypes.HWND),
                        ("uID", wintypes.UINT), ("uFlags", wintypes.UINT),
                        ("uCallbackMessage", wintypes.UINT), ("hIcon", wintypes.HICON),
                        ("szTip", wintypes.WCHAR * 128), ("dwState", wintypes.DWORD),
                        ("dwStateMask", wintypes.DWORD), ("szInfo", wintypes.WCHAR * 256),
                        ("uVersion", wintypes.UINT), ("szInfoTitle", wintypes.WCHAR * 64),
                        ("dwInfoFlags", wintypes.DWORD), ("guidItem", GUID),
                        ("hBalloonIcon", wintypes.HICON)]

        LRESULT = ctypes.c_ssize_t
        WNDPROC = ctypes.WINFUNCTYPE(
            LRESULT, wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM)

        class WNDCLASSW(ctypes.Structure):
            _fields_ = [("style", wintypes.UINT), ("lpfnWndProc", WNDPROC),
                        ("cbClsExtra", ctypes.c_int), ("cbWndExtra", ctypes.c_int),
                        ("hInstance", wintypes.HINSTANCE), ("hIcon", wintypes.HICON),
                        ("hCursor", wintypes.HANDLE), ("hbrBackground", wintypes.HBRUSH),
                        ("lpszMenuName", wintypes.LPCWSTR), ("lpszClassName", wintypes.LPCWSTR)]

        user32, shell32, kernel32 = (
            ctypes.windll.user32, ctypes.windll.shell32, ctypes.windll.kernel32)
        user32.DefWindowProcW.restype = LRESULT
        user32.DefWindowProcW.argtypes = [wintypes.HWND, wintypes.UINT,
                                          wintypes.WPARAM, wintypes.LPARAM]
        user32.RegisterClassW.restype = wintypes.ATOM
        user32.RegisterClassW.argtypes = [ctypes.POINTER(WNDCLASSW)]
        user32.CreateWindowExW.restype = wintypes.HWND
        user32.CreateWindowExW.argtypes = [
            wintypes.DWORD, wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.DWORD,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, wintypes.HWND,
            wintypes.HMENU, wintypes.HINSTANCE, wintypes.LPVOID]
        user32.DestroyWindow.argtypes = [wintypes.HWND]
        user32.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT,
                                        wintypes.WPARAM, wintypes.LPARAM]
        user32.CreatePopupMenu.restype = wintypes.HMENU
        user32.AppendMenuW.argtypes = [wintypes.HMENU, wintypes.UINT,
                                       ctypes.c_size_t, wintypes.LPCWSTR]
        user32.TrackPopupMenu.restype = wintypes.UINT
        user32.TrackPopupMenu.argtypes = [
            wintypes.HMENU, wintypes.UINT, ctypes.c_int, ctypes.c_int, ctypes.c_int,
            wintypes.HWND, ctypes.c_void_p]
        user32.DestroyMenu.argtypes = [wintypes.HMENU]
        user32.GetCursorPos.argtypes = [ctypes.POINTER(wintypes.POINT)]
        user32.SetForegroundWindow.argtypes = [wintypes.HWND]
        user32.GetMessageW.argtypes = [ctypes.POINTER(wintypes.MSG), wintypes.HWND,
                                       wintypes.UINT, wintypes.UINT]
        user32.TranslateMessage.argtypes = [ctypes.POINTER(wintypes.MSG)]
        user32.DispatchMessageW.argtypes = [ctypes.POINTER(wintypes.MSG)]
        user32.LoadImageW.restype = wintypes.HANDLE
        user32.LoadImageW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR,
                                      wintypes.UINT, ctypes.c_int, ctypes.c_int,
                                      wintypes.UINT]
        kernel32.GetModuleHandleW.restype = wintypes.HMODULE
        kernel32.GetModuleHandleW.argtypes = [wintypes.LPCWSTR]
        kernel32.GetCurrentThreadId.restype = wintypes.DWORD
        shell32.Shell_NotifyIconW.argtypes = [wintypes.DWORD,
                                              ctypes.POINTER(NOTIFYICONDATAW)]
        icon_path = Path(tempfile.gettempdir()) / "pfc-notification.ico"
        notify = None
        icon = 0

        def add_icon() -> None:
            if notify is None:
                return
            notify.uFlags = NIF_MESSAGE | NIF_ICON | NIF_TIP
            notify.uVersion = 0
            shell32.Shell_NotifyIconW(NIM_ADD, ctypes.byref(notify))
            notify.uVersion = NOTIFYICON_VERSION_4
            shell32.Shell_NotifyIconW(NIM_SETVERSION, ctypes.byref(notify))

        def show_menu(hwnd) -> None:
            menu = user32.CreatePopupMenu()
            if not menu:
                return
            user32.AppendMenuW(menu, MF_STRING, OPEN_COMMAND, self.open_label)
            flags = MF_STRING | (MF_CHECKED if self.auto_start_enabled else 0)
            user32.AppendMenuW(menu, flags, AUTOSTART_COMMAND, self.auto_start_label)
            user32.AppendMenuW(menu, MF_SEPARATOR, 0, None)
            user32.AppendMenuW(menu, MF_STRING, EXIT_COMMAND, self.exit_label)
            point = wintypes.POINT()
            user32.GetCursorPos(ctypes.byref(point))
            user32.SetForegroundWindow(hwnd)
            command = user32.TrackPopupMenu(
                menu, TPM_RIGHTBUTTON | TPM_RETURNCMD, point.x, point.y, 0, hwnd, None)
            user32.DestroyMenu(menu)
            user32.PostMessageW(hwnd, WM_NULL, 0, 0)
            if command == OPEN_COMMAND:
                self.actions.put("show")
            elif command == AUTOSTART_COMMAND:
                self.actions.put("toggle_autostart")
            elif command == EXIT_COMMAND:
                self.actions.put("exit")

        taskbar_created = user32.RegisterWindowMessageW("TaskbarCreated")

        @WNDPROC
        def window_proc(hwnd, message, wparam, lparam):
            if message == CALLBACK_MESSAGE:
                event = int(lparam) & 0xFFFF
                if event in (WM_LBUTTONUP, WM_LBUTTONDBLCLK):
                    self.actions.put("show")
                elif event == WM_RBUTTONUP:
                    show_menu(hwnd)
                return 0
            if message == taskbar_created:
                add_icon()
                return 0
            if message == WM_CLOSE:
                if notify is not None:
                    shell32.Shell_NotifyIconW(NIM_DELETE, ctypes.byref(notify))
                user32.DestroyWindow(hwnd)
                return 0
            if message == WM_DESTROY:
                user32.PostQuitMessage(0)
                return 0
            return user32.DefWindowProcW(hwnd, message, wparam, lparam)

        try:
            icon_path.write_bytes(self.icon_bytes)
            instance = kernel32.GetModuleHandleW(None)
            class_name = f"PFCTrayWindow_{id(self)}"
            window_class = WNDCLASSW()
            window_class.lpfnWndProc = window_proc
            window_class.hInstance = instance
            window_class.lpszClassName = class_name
            if not user32.RegisterClassW(ctypes.byref(window_class)):
                raise ctypes.WinError()
            hwnd = user32.CreateWindowExW(
                0, class_name, "PFC Tray", 0, 0, 0, 0, 0, 0, 0, instance, None)
            if not hwnd:
                raise ctypes.WinError()
            self._hwnd = hwnd
            self._thread_id = kernel32.GetCurrentThreadId()
            icon = user32.LoadImageW(None, str(icon_path), IMAGE_ICON, 32, 32,
                                     LR_LOADFROMFILE)
            if not icon:
                raise ctypes.WinError()
            notify = NOTIFYICONDATAW()
            notify.cbSize = ctypes.sizeof(notify)
            notify.hWnd = hwnd
            notify.uID = 1
            notify.uCallbackMessage = CALLBACK_MESSAGE
            notify.hIcon = icon
            notify.szTip = "PFC — Python File Commander"
            add_icon()
            if self._stop_requested.is_set():
                user32.PostMessageW(hwnd, WM_CLOSE, 0, 0)
            message = wintypes.MSG()
            while user32.GetMessageW(ctypes.byref(message), None, 0, 0) > 0:
                user32.TranslateMessage(ctypes.byref(message))
                user32.DispatchMessageW(ctypes.byref(message))
        except Exception as exc:
            self.error = exc
        finally:
            if notify is not None:
                shell32.Shell_NotifyIconW(NIM_DELETE, ctypes.byref(notify))
            if icon:
                user32.DestroyIcon(icon)
            try:
                icon_path.unlink(missing_ok=True)
            except OSError:
                pass
            self._hwnd = 0


"""Event-driven directory change notifications with a portable fallback boundary."""

import ctypes
import os
import queue
import threading
import time
from ctypes import wintypes
from pathlib import Path


def directory_key(path: Path) -> str:
    """Return a stable key for matching Windows paths across panes and events."""
    return os.path.normcase(os.path.abspath(str(path)))


def is_local_watch_path(path: Path) -> bool:
    """Native change notifications are reserved for local filesystem paths."""
    return os.name == "nt" and not str(path).startswith("\\\\")


class _WindowsDirectoryWatcher:
    _FILE_LIST_DIRECTORY = 0x0001
    _SHARE_ALL = 0x00000001 | 0x00000002 | 0x00000004
    _OPEN_EXISTING = 3
    _BACKUP_SEMANTICS = 0x02000000
    _NOTIFY_FILTER = (0x00000001 | 0x00000002 | 0x00000004 |
                      0x00000008 | 0x00000010 | 0x00000020)

    def __init__(self, path: Path, events: queue.Queue) -> None:
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        self._kernel32 = kernel32
        kernel32.CreateFileW.argtypes = (
            wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID,
            wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE,
        )
        kernel32.CreateFileW.restype = wintypes.HANDLE
        kernel32.ReadDirectoryChangesW.argtypes = (
            wintypes.HANDLE, wintypes.LPVOID, wintypes.DWORD, wintypes.BOOL,
            wintypes.DWORD, ctypes.POINTER(wintypes.DWORD), wintypes.LPVOID,
            wintypes.LPVOID,
        )
        kernel32.ReadDirectoryChangesW.restype = wintypes.BOOL
        kernel32.CancelIoEx.argtypes = (wintypes.HANDLE, wintypes.LPVOID)
        kernel32.CancelIoEx.restype = wintypes.BOOL
        kernel32.CloseHandle.argtypes = (wintypes.HANDLE,)
        kernel32.CloseHandle.restype = wintypes.BOOL
        self.path = Path(path)
        self._events = events
        self._lock = threading.Lock()
        self._stopping = threading.Event()
        handle = kernel32.CreateFileW(
            str(self.path), self._FILE_LIST_DIRECTORY, self._SHARE_ALL, None,
            self._OPEN_EXISTING, self._BACKUP_SEMANTICS, None,
        )
        if handle == wintypes.HANDLE(-1).value:
            raise ctypes.WinError(ctypes.get_last_error())
        self._handle = handle
        self._thread = threading.Thread(
            target=self._run, name=f"PFC-Watch-{self.path.name}", daemon=True)

    @property
    def alive(self) -> bool:
        return self._thread.is_alive() and not self._stopping.is_set()

    def start(self) -> None:
        self._thread.start()

    def _run(self) -> None:
        buffer = ctypes.create_string_buffer(64 * 1024)
        returned = wintypes.DWORD()
        while not self._stopping.is_set():
            with self._lock:
                handle = self._handle
            if handle is None:
                break
            ok = self._kernel32.ReadDirectoryChangesW(
                handle, buffer, len(buffer), False, self._NOTIFY_FILTER,
                ctypes.byref(returned), None, None,
            )
            if not ok:
                break
            if returned.value:
                self._events.put(self.path)

    def stop(self) -> None:
        self._stopping.set()
        with self._lock:
            handle, self._handle = self._handle, None
        if handle is not None:
            self._kernel32.CancelIoEx(handle, None)
            self._kernel32.CloseHandle(handle)
        if self._thread.is_alive():
            self._thread.join(timeout=.2)


class DirectoryWatchManager:
    """Keep one native watcher per unique visible directory."""

    def __init__(self, watcher_factory=None, supported: bool | None = None) -> None:
        self.events: queue.Queue = queue.Queue()
        self.supported = os.name == "nt" if supported is None else supported
        self._factory = watcher_factory or _WindowsDirectoryWatcher
        self._watchers = {}
        self._retry_after = {}

    def sync(self, paths) -> set[str]:
        desired = {directory_key(path): Path(path) for path in paths}
        for key in list(self._watchers):
            watcher = self._watchers[key]
            if key not in desired or not watcher.alive:
                watcher.stop()
                del self._watchers[key]
                if key in desired:
                    self._retry_after[key] = time.monotonic() + 5.0
        if self.supported:
            now = time.monotonic()
            for key, path in desired.items():
                if key in self._watchers or now < self._retry_after.get(key, 0):
                    continue
                try:
                    watcher = self._factory(path, self.events)
                    watcher.start()
                    self._watchers[key] = watcher
                    self._retry_after.pop(key, None)
                except OSError:
                    self._retry_after[key] = now + 5.0
        return set(self._watchers)

    def drain(self) -> set[str]:
        changed = set()
        try:
            while True:
                changed.add(directory_key(self.events.get_nowait()))
        except queue.Empty:
            return changed

    def close(self) -> None:
        for watcher in list(self._watchers.values()):
            watcher.stop()
        self._watchers.clear()



import os
import subprocess
import time
import xml.etree.ElementTree as ET
from pathlib import Path


_CACHE: dict[str, tuple[float, dict[str, str]]] = {}
_CACHE_SECONDS = 3.0
_PRIORITY = {"conflict": 5, "modified": 4, "added": 3, "untracked": 2,
             "deleted": 1, "clean": 0}


def invalidate_vcs_cache():
    """A client dialog finished; the next overlay request must use fresh metadata."""
    _CACHE.clear()


def _run_options() -> dict:
    """Keep background VCS commands invisible in Windows GUI launches."""
    return {"creationflags": getattr(subprocess, "CREATE_NO_WINDOW", 0)}


def _merge(statuses: dict[str, str], path: Path, status: str, root: Path) -> None:
    try:
        current = path.resolve()
    except OSError:
        current = Path(os.path.abspath(path))
    while current == root or root in current.parents:
        key = os.path.normcase(str(current))
        if key not in statuses or _PRIORITY.get(status, 0) > _PRIORITY.get(statuses[key], 0):
            statuses[key] = status
        if current == root:
            break
        current = current.parent


def _find_root(folder: Path, marker: str) -> Path | None:
    current = folder.resolve()
    for candidate in (current, *current.parents):
        if (candidate / marker).exists():
            return candidate
    return None


def is_metadata_path(folder: Path) -> bool:
    """VCS internals are data, not a working-tree location to status-scan."""
    try:
        parts = folder.resolve().parts
    except OSError:
        parts = Path(os.path.abspath(folder)).parts
    return any(part.casefold() in {".git", ".svn"} for part in parts)


def _git_code_status(code: str) -> str:
    return ("conflict" if "U" in code or code in {"AA", "DD"} else
            "untracked" if code == "??" else
            "added" if "A" in code else
            "deleted" if "D" in code else "modified")


def _git_root_summary(root: Path) -> str | None:
    """Return one overlay state for a repository root shown from its parent."""
    try:
        result = subprocess.run(
            ["git", "-C", str(root), "status", "--porcelain=v1", "--branch", "-z",
             "--untracked-files=all"], capture_output=True, timeout=4, **_run_options())
    except (OSError, subprocess.SubprocessError, subprocess.TimeoutExpired):
        return None
    if result.returncode:
        return None
    summary = "clean"
    records = result.stdout.split(b"\0")
    index = 0
    while index < len(records):
        record = records[index]
        index += 1
        if record.startswith(b"## "):
            if b"[ahead " in record or b"[behind " in record:
                summary = "modified"
            continue
        if len(record) < 4:
            continue
        code = record[:2].decode("ascii", "replace")
        if "R" in code or "C" in code:
            index += 1
        status = _git_code_status(code)
        if _PRIORITY[status] > _PRIORITY[summary]:
            summary = status
    return summary


def _child_repository_statuses(folder: Path) -> dict[str, str]:
    """Expose direct child repository roots without recursively scanning folders."""
    statuses: dict[str, str] = {}
    try:
        children = tuple(folder.iterdir())
    except OSError:
        return statuses
    for child in children:
        try:
            if not child.is_dir():
                continue
            if (child / ".git").exists():
                status = _git_root_summary(child)
            elif (child / ".svn").exists():
                nested = _svn_status(child)
                status = status_for(nested or {}, child) or "clean"
            else:
                continue
            if status is not None:
                statuses[os.path.normcase(str(child.resolve()))] = status
        except OSError:
            continue
    return statuses


def _git_status(folder: Path) -> dict[str, str] | None:
    root = _find_root(folder, ".git")
    if root is None:
        return None
    relative = os.path.relpath(folder, root)
    command = ["git", "-C", str(root), "status", "--porcelain=v1", "-z",
               "--untracked-files=all", "--", relative]
    result = subprocess.run(command, capture_output=True, timeout=4, **_run_options())
    if result.returncode:
        return {}
    statuses: dict[str, str] = {}
    tracked = subprocess.run(["git", "-C", str(root), "ls-files", "-z", "--", relative],
                             capture_output=True, timeout=4, **_run_options())
    if tracked.returncode == 0:
        for raw_path in tracked.stdout.split(b"\0"):
            if raw_path:
                _merge(statuses, root / raw_path.decode("utf-8", "surrogateescape"),
                       "clean", root)
    records = result.stdout.split(b"\0")
    index = 0
    while index < len(records):
        record = records[index]
        index += 1
        if len(record) < 4:
            continue
        code = record[:2].decode("ascii", "replace")
        raw_path = record[3:].decode("utf-8", "surrogateescape")
        if "R" in code or "C" in code:
            index += 1  # porcelain -z adds the source name after the destination.
        status = _git_code_status(code)
        _merge(statuses, root / raw_path, status, root)
    return statuses


def _svn_status(folder: Path) -> dict[str, str] | None:
    root = _find_root(folder, ".svn")
    if root is None:
        return None
    try:
        result = subprocess.run(["svn", "status", "-v", "--xml", str(folder)],
                                capture_output=True, text=True, errors="replace", timeout=4,
                                **_run_options())
    except (OSError, subprocess.TimeoutExpired):
        return {}
    if result.returncode:
        return {}
    mapping = {"conflicted": "conflict", "added": "added", "unversioned": "untracked",
               "missing": "deleted", "deleted": "deleted", "modified": "modified",
               "replaced": "modified", "normal": "clean"}
    statuses: dict[str, str] = {}
    try:
        document = ET.fromstring(result.stdout)
    except ET.ParseError:
        return statuses
    for entry in document.findall(".//entry"):
        wc = entry.find("wc-status")
        if wc is None:
            continue
        status = mapping.get(wc.get("item", ""))
        if status:
            _merge(statuses, Path(entry.get("path", "")), status, root)
    return statuses


def folder_statuses(folder: Path) -> dict[str, str]:
    """Return Git/SVN overlay states keyed by normalized absolute path."""
    if is_metadata_path(folder):
        return {}
    key = os.path.normcase(str(folder.resolve()))
    cached = _CACHE.get(key)
    now = time.monotonic()
    if cached and now - cached[0] < _CACHE_SECONDS:
        return cached[1]
    try:
        statuses = _git_status(folder)
        if statuses is None:
            statuses = _svn_status(folder)
        if statuses is None:
            statuses = _child_repository_statuses(folder)
        value = statuses or {}
        # A directly contained repository remains its own status boundary even
        # when the folder being viewed is itself inside another work tree.
        # This also covers nested repositories that are not registered as Git
        # submodules.
        value.update(_child_repository_statuses(folder))
    except (OSError, subprocess.SubprocessError, subprocess.TimeoutExpired):
        value = {}
    _CACHE[key] = (now, value)
    return value


def status_for(statuses: dict[str, str], path: Path) -> str | None:
    try:
        key = os.path.normcase(str(path.resolve()))
    except OSError:
        key = os.path.normcase(os.path.abspath(path))
    return statuses.get(key)


"""Compact lock badges rendered from geometry, without fonts or image dependencies."""
from functools import lru_cache
import math



@lru_cache(maxsize=48)
def tab_lock_icon_png(mode: str, size: int, background: str, foreground: str) -> bytes:
    """Render at 4x resolution; cache bytes, never Tk images across interpreters."""
    if mode not in {'locked', 'reset'}:
        raise ValueError('A badge requires a locked or reset tab')
    if not 16 <= size <= 128:
        raise ValueError('Tab badge size must be between 16 and 128 pixels')
    supersample = 4
    extent = size * supersample
    unit = extent / 32
    pixels = bytearray(extent * extent * 4)
    face, ink = _hex_rgba(background), _hex_rgba(foreground)

    def paint(bounds, inside, color):
        x1, y1, x2, y2 = bounds
        for y in range(max(0, math.floor(y1*unit)), min(extent, math.ceil(y2*unit))):
            py = (y+.5)/unit
            for x in range(max(0, math.floor(x1*unit)), min(extent, math.ceil(x2*unit))):
                if inside((x+.5)/unit, py):
                    index = (y*extent+x)*4
                    pixels[index:index+4] = bytes(color)

    def rounded(x1, y1, x2, y2, radius, color):
        def inside(x, y):
            cx = max(x1+radius, min(x, x2-radius))
            cy = max(y1+radius, min(y, y2-radius))
            return (x-cx)**2 + (y-cy)**2 <= radius**2
        paint((x1, y1, x2, y2), inside, color)

    def line(x1, y1, x2, y2, width, color):
        r = width/2
        paint((min(x1,x2)-r, min(y1,y2)-r, max(x1,x2)+r, max(y1,y2)+r),
              lambda x,y: _distance_to_segment(x,y,x1,y1,x2,y2) <= r, color)

    # Identical neutral tile for BOTH modes. A fine contrasting edge keeps the
    # light tile legible on a custom pastel tab in the dark application theme.
    rounded(.5, .5, 31.5, 31.5, 5, ink)
    rounded(1.3, 1.3, 30.7, 30.7, 4.2, face)
    if mode == 'locked':
        rounded(9, 5, 23, 21, 7, ink)
        rounded(12, 8, 20, 20, 4, face)
        rounded(6.5, 14, 25.5, 27, 2, ink)
        rounded(14.6, 17.5, 17.4, 23.5, 1.4, face)
    else:
        # Small closed lock at upper right; a large hooked arrow dominates the
        # lower/left silhouette. Distinguishable even with identical tile colors.
        rounded(18, 4, 27, 15, 4.5, ink)
        rounded(20.5, 6.5, 24.5, 15, 2, face)
        rounded(16, 10, 29, 18, 1.5, ink)
        line(11, 15, 5, 21, 3, ink)
        line(5, 21, 11, 27, 3, ink)
        line(5, 21, 22, 21, 3, ink)
        # Right semicircle connects the top return stroke to its lower tail.
        paint((20, 19.5, 29, 29.5),
              lambda x,y: x >= 22 and 1 <= (x-22)**2+(y-24.5)**2 <= 25, ink)
        line(16, 28, 22, 28, 3, ink)
    return _rgba_png_downsample(pixels, size, supersample)

import ctypes
import os
import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk


def virtual_screen_bounds(widget) -> tuple[int, int, int, int]:
    """Return the complete desktop bounds, including negative monitor origins."""
    if os.name == "nt":
        user32 = ctypes.windll.user32
        return tuple(user32.GetSystemMetrics(index) for index in (76, 77, 78, 79))
    return (widget.winfo_vrootx(), widget.winfo_vrooty(),
            widget.winfo_vrootwidth(), widget.winfo_vrootheight())


def clamp_popup_position(x: int, y: int, width: int, height: int,
                         bounds: tuple[int, int, int, int]) -> tuple[int, int]:
    left, top, screen_width, screen_height = bounds
    right, bottom = left + screen_width, top + screen_height
    return (max(left, min(int(x), right - int(width))),
            max(top, min(int(y), bottom - int(height))))


