        ttk.Button(folder_tools, text=tr("Collapse All"), command=self.collapse_all).pack(side="left", padx=(3, 0))
        ttk.Button(folder_tools, text=tr("Set Base Folder"), command=self.set_base_folder).pack(side="left", padx=(8, 0))
