def ensure_config_defaults(config: configparser.ConfigParser) -> None:
    defaults = {
        "view": {"font_size": "small", "auto_font_size": "true",
                 "tab_style": "right_skirt", "panel_count": "2",
                 "ui_language": "en", "color_scheme": "light", "extension_effect": "true",
                 "mix_sorting": "true", "right_click_menu": "explorer",
                 "long_name_scrolling": "true", "column_ext": "true",
                 "column_size": "true", "column_modified": "true",
                 "date_order": "ymd", "time_style": "24", "size_emphasis": "true",
                 "onedrive_overlay": "true", "vcs_overlay": "true"},
        "refresh": {"auto_refresh": "true", "active_interval_ms": "2000",
                    "background_interval_ms": "10000", "network_interval_ms": "5000"},
        "operations": {"send_delete_to_recycle_bin": "true", "continue_after_error": "true"},
        "navigation": {"favorites": "[]", "recent_folders": "[]"},
        "startup": {"auto_start": "true"},
    }
    for section, values in defaults.items():
        if not config.has_section(section):
            config.add_section(section)
        for key, value in values.items():
            if not config.has_option(section, key):
                config.set(section, key, value)


def write_config_atomic(config: configparser.ConfigParser, path: Path) -> None:
    temporary = path.with_suffix(path.suffix + ".tmp")
    try:
        with temporary.open("w", encoding="utf-8") as stream:
            config.write(stream)
        temporary.replace(path)
    except OSError:
        try: temporary.unlink(missing_ok=True)
        except OSError: pass
        raise


def config_json(value, **kwargs) -> str:
    """Escape literal percent signs only at the ConfigParser storage boundary."""
    return json.dumps(value, **kwargs).replace("%", "%%")


def hide_private_console() -> bool:
    """Hide a console created only for PFC, without hiding a user's shell."""
    if os.name != "nt":
        return False
    kernel32, user32 = ctypes.windll.kernel32, ctypes.windll.user32
    kernel32.GetConsoleWindow.restype = ctypes.c_void_p
    process_ids = (ctypes.c_uint32 * 64)()
    count = kernel32.GetConsoleProcessList(process_ids, len(process_ids))
    # An existing CMD/PowerShell console includes at least the shell and Python.
    if count != 1:
        return False
    window = kernel32.GetConsoleWindow()
    if not window:
        return False
    user32.ShowWindow.argtypes = [ctypes.c_void_p, ctypes.c_int]
    user32.ShowWindow(window, 0)  # SW_HIDE
    return True


def admin_launch_spec(path: Path, python_executable: str | None = None) -> tuple[str, str | None]:
    """Return the Windows elevated executable and parameters for a supported file."""
    path = path.resolve()
    suffix = path.suffix.casefold()
    quoted = f'"{path}"'
    if suffix in {".py", ".pyw"}:
        return python_executable or sys.executable, quoted
    if suffix == ".msi":
        return "msiexec.exe", f"/i {quoted}"
    if suffix in {".bat", ".cmd"}:
        return "cmd.exe", f'/c ""{path}""'
    if suffix == ".ps1":
        return "powershell.exe", f"-NoProfile -ExecutionPolicy Bypass -File {quoted}"
    return str(path), None


def enable_windows_dpi_awareness() -> bool:
    """Request the sharpest supported Windows DPI mode before Tk is created."""
    if os.name != "nt":
        return False
    try:
        bits = ctypes.sizeof(ctypes.c_void_p) * 8
        context = ctypes.c_void_p(-4 & ((1 << bits) - 1))  # PER_MONITOR_AWARE_V2
        if ctypes.windll.user32.SetProcessDpiAwarenessContext(context):
            return True
    except (AttributeError, OSError, ValueError):
        pass
    try:
        if ctypes.windll.shcore.SetProcessDpiAwareness(2) in (0, -2147024891):
            return True
    except (AttributeError, OSError):
        pass
    try:
        return bool(ctypes.windll.user32.SetProcessDPIAware())
    except (AttributeError, OSError):
        return False


def preferred_font_families(available) -> tuple[str, str]:
    names = {str(name).casefold(): str(name) for name in available}
    interface = next((names[name.casefold()] for name in
                      ("Segoe UI", "Ubuntu", "Noto Sans", "DejaVu Sans")
                      if name.casefold() in names), "TkDefaultFont")
    fixed = next((names[name.casefold()] for name in
                  ("Cascadia Mono", "Consolas", "Ubuntu Mono", "DejaVu Sans Mono")
                  if name.casefold() in names), "TkFixedFont")
    return interface, fixed


def configure_native_fonts(root) -> None:
    """Use ClearType-friendly native families while retaining current font sizes."""
    interface, fixed = preferred_font_families(tkfont.families(root))
    for name in ("TkDefaultFont", "TkTextFont", "TkMenuFont", "TkHeadingFont",
                 "TkCaptionFont", "TkSmallCaptionFont", "TkTooltipFont"):
        try:
            tkfont.nametofont(name, root=root).configure(family=interface)
        except tk.TclError:
            pass
    try:
        tkfont.nametofont("TkFixedFont", root=root).configure(family=fixed)
    except tk.TclError:
        pass


def navigation_destination(path: Path) -> tuple[Path, Path | None]:
    """Return the folder to open and an existing file to select, if supplied."""
    target = path.expanduser().resolve()
    return (target.parent, target) if target.is_file() else (target, None)


def nearest_accessible_folder(path: Path) -> Path:
    """Walk upward from *path* until a readable folder is found."""
    candidate = Path(path).expanduser()
    try:
        candidate = candidate.resolve()
    except OSError:
        candidate = Path(os.path.abspath(candidate))
    while True:
        try:
            if candidate.is_dir():
                with os.scandir(candidate):
                    return candidate
        except OSError:
            pass
        parent = candidate.parent
        if parent == candidate:
            break
        candidate = parent
    for fallback in (Path.home(), *roots()):
        try:
            if fallback.is_dir():
                with os.scandir(fallback):
                    return fallback.resolve()
        except OSError:
            pass
    return Path.home()


def shortcut_path_for(source: Path, folder: Path) -> Path:
    suffix = ".lnk" if os.name == "nt" else ".shortcut"
    base = f"{source.stem if source.is_file() else source.name} - Shortcut"
    candidate = folder / f"{base}{suffix}"
    number = 2
    while candidate.exists():
        candidate = folder / f"{base} ({number}){suffix}"
        number += 1
    return candidate


def create_shortcut_file(source: Path, shortcut: Path) -> Path:
    """Create a native Windows shortcut or a portable symlink."""
    source, shortcut = source.resolve(), shortcut.resolve()
    if os.name == "nt":
        script = ("$w=New-Object -ComObject WScript.Shell;"
                  "$s=$w.CreateShortcut($env:PFC_SHORTCUT_PATH);"
                  "$s.TargetPath=$env:PFC_SHORTCUT_SOURCE;"
                  "$s.WorkingDirectory=(Split-Path -LiteralPath $env:PFC_SHORTCUT_SOURCE -Parent);"
                  "$s.Save()")
        environment = os.environ.copy()
        environment["PFC_SHORTCUT_SOURCE"] = str(source)
        environment["PFC_SHORTCUT_PATH"] = str(shortcut)
        subprocess.run(
            ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", script],
            check=True, capture_output=True, env=environment,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    else:
        shortcut.symlink_to(source, target_is_directory=source.is_dir())
    return shortcut


def folder_history_selection(previous: Path, target: Path,
                             remembered: dict[Path, Path]) -> Path | None:
    """Choose the row to restore after entering or leaving a folder."""
    if previous != target and previous.parent == target:
        return previous
    return remembered.get(target)


def transfer_target_index(source_index: int, panel_count: int) -> int:
    """Return the intuitive adjacent destination for F5/F6 operations."""
    if panel_count < 2:
        return 0
    source_index = max(0, min(source_index, panel_count - 1))
    return 1 if source_index == 0 else source_index - 1


def version_key(value: str) -> tuple[int, ...]:
    """Return a comparable numeric key for a dotted PFC version."""
    parts = value.strip().lstrip("vV").split(".")
    if not parts or any(not part.isdigit() for part in parts):
        raise ValueError(f"Invalid PFC version: {value}")
    return tuple(int(part) for part in parts)


def downloaded_pfc_version(payload: bytes) -> str:
    """Validate a downloaded portable script and return its declared version."""
    if not payload or len(payload) > UPDATE_SIZE_LIMIT:
        raise ValueError("Downloaded pfc.py has an invalid size.")
    source = payload.decode("utf-8")
    match = re.search(r'^__version__\s*=\s*["\'](\d+\.\d+\.\d+)["\']',
                      source, re.MULTILINE)
    if match is None or "Python File Commander" not in source:
        raise ValueError("Downloaded file is not a valid PFC portable script.")
    compile(source, "pfc.py", "exec")
    return match.group(1)


def _download_update_file(url: str, size_limit: int, progress=None,
                          label: str = "pfc.py") -> bytes:
    request = urllib.request.Request(url, headers={
        "User-Agent": "Python-File-Commander-Updater",
    })
    with urllib.request.urlopen(request, timeout=20) as response:
        declared = response.headers.get("Content-Length")
        if declared and int(declared) > size_limit:
            raise ValueError(f"Downloaded {label or 'update data'} is too large.")
        total = int(declared) if declared else 0
        chunks, received = [], 0
        while True:
            chunk = response.read(64 * 1024)
            if not chunk:
                break
            chunks.append(chunk); received += len(chunk)
            if received > size_limit:
                raise ValueError(f"Downloaded {label or 'update data'} is too large.")
            if progress:
                progress(received, total or max(received + 1, size_limit), label)
        payload = b"".join(chunks)
        if progress:
            progress(total or received, total or received, label)
    return payload


def fetch_pfc_update(url: str = UPDATE_URL, progress=None) -> tuple[str, bytes]:
    payload = _download_update_file(url, UPDATE_SIZE_LIMIT, progress)
    return downloaded_pfc_version(payload), payload


def replace_portable_script(target: Path, payload: bytes) -> None:
    """Atomically replace pfc.py only after full validation succeeds."""
    downloaded_pfc_version(payload)
    temporary = target.with_name(f".{target.name}.update")
    try:
        with temporary.open("wb") as stream:
            stream.write(payload); stream.flush(); os.fsync(stream.fileno())
        os.replace(temporary, target)
    finally:
        temporary.unlink(missing_ok=True)


def is_noop_drag_drop(items: list[Path], destination: Path) -> bool:
    """Treat a drag back to its source folder (or onto itself) as cancellation."""
    if not items:
        return False
    try:
        resolved_destination = destination.resolve()
        resolved_items = [item.resolve() for item in items]
    except OSError:
        return False
    if all(item.parent == resolved_destination for item in resolved_items):
        return True
    return len(resolved_items) == 1 and resolved_items[0] == resolved_destination


def scaled_tree_row_height(font_linespace: int, scale: float) -> int:
    """Keep text descenders clear while icons occupy about 90% of each row."""
    vertical_space = max(8, round(8 * scale))
    return max(24, font_linespace + vertical_space)


def automatic_font_size(window_width: int, window_height: int, panel_count: int,
                        screen_width: int | None = None) -> str:
    """Choose the largest scale that keeps each visible file panel usable."""
    per_panel = max(1, window_width) / max(1, panel_count)
    height_level = (4 if window_height >= 1250 else 3 if window_height >= 1050
                    else 2 if window_height >= 850 else 1 if window_height >= 650 else 0)
    width_level = (4 if per_panel >= 1200 else 3 if per_panel >= 1000
                   else 2 if per_panel >= 750 else 1 if per_panel >= 500 else 0)
    level = min(height_level, width_level)
    if screen_width and screen_width > 0:
        occupied_width = max(0.0, window_width / screen_width)
        # Native DPI scaling already keeps text readable. A snapped half-screen
        # window must not be mistaken for an XXL layout merely because the
        # monitor has a very high physical pixel count.
        if occupied_width <= .60:
            level = 0
        elif occupied_width <= .75:
            level = min(level, 1)
    return ("small", "medium", "large", "xl", "xxl")[level]


def extension_column_width(measure) -> int:
    """Keep Ext to four wide Latin characters and return the rest to Name."""
    return max(32, measure("MMMM"))


def ellipsize_middle(text: str, max_width: int, measure) -> str:
    """Fit text in a pixel width while preserving both its start and useful suffix."""
    if max_width <= 0:
        return ""
    if measure(text) <= max_width:
        return text
    ellipsis = "…"
    if measure(ellipsis) > max_width:
        return ""
    low, high = 0, len(text)
    while low < high:
        keep = (low + high + 1) // 2
        left = (keep + 1) * 3 // 5
        candidate = text[:left].rstrip() + ellipsis + text[-(keep - left):].lstrip()
        if measure(candidate) <= max_width:
            low = keep
        else:
            high = keep - 1
    left = (low + 1) * 3 // 5
    right = low - left
    return text[:left].rstrip() + ellipsis + (text[-right:].lstrip() if right else "")


def clipboard_header_widths(window_width: int, left_width: int, icon_width: int) -> tuple[int, int]:
    """Return bounded frame/text widths that can never extend past the header."""
    frame_width = max(0, window_width - left_width - 24)
    return frame_width, max(0, frame_width - icon_width - 4)


def split_clipboard_summary(label: str) -> tuple[str, str]:
    """Split a localized Clipboard prefix from its detail text."""
    for separator in (": ", "："):
        if separator in label:
            prefix, detail = label.split(separator, 1)
            return prefix + separator.rstrip(), detail
    return label, ""


def relaunch_with_pythonw() -> bool:
    """Hand a Windows GUI launch from python.exe to pythonw.exe once."""
    if os.name != "nt" or os.environ.get("PFC_PYTHONW") == "1":
        return False
    executable = Path(sys.executable)
    if executable.name.casefold() == "pythonw.exe":
        return False
    pythonw = executable.with_name("pythonw.exe")
    if not pythonw.is_file():
        return False
    environment = os.environ.copy()
    environment["PFC_PYTHONW"] = "1"
    subprocess.Popen([str(pythonw), *sys.argv], cwd=os.getcwd(), env=environment,
                     close_fds=True, creationflags=0x00000008)  # DETACHED_PROCESS
    return True


class FilePane(ttk.Frame):
    columns = ("ext", "size", "modified")
    all_sort_columns = ("name", "ext", "size", "modified")
    base_widths = {"name": 300, "ext": 55, "size": 85, "modified": 135}
    default_mix_sorting = True

    def __init__(self, master: tk.Misc, on_activate, on_change=lambda: None,
                 on_drag=lambda _action, _pane, _event: None,
                 on_context=lambda _pane, _path, _x, _y: None,
                 on_native_context=lambda _pane, _path, _x, _y: None,
                 on_open_file=lambda _pane, _path: False,
                 on_exit_archive=lambda _pane: False) -> None:
        super().__init__(master)
        self.on_activate = on_activate
        self.on_change = on_change
        self.on_drag = on_drag
        self.on_context = on_context
        self.on_native_context = on_native_context
        self.on_open_file = on_open_file
        self.on_exit_archive = on_exit_archive
        self.archive_session: ArchiveSession | None = None
        self.path = Path.home()
        self.history: list[Path] = []
        self.folder_selections: dict[Path, Path] = {}
        self.sort_column = "name"
        self.reverse = False
        self.mix_sorting = self.default_mix_sorting
        self.show_hidden = False
        self.show_system = False
        self.show_extensions = True
        self._date_values = {}
        self.mode = "files"
        self.view_mode = "list"
        self.display_title = self.path.name or str(self.path)
        self.lock_mode = "unlocked"
        self.locked_path: Path | None = None
        self.on_locked_navigation = lambda _path: None
        self._signature = None
        self.quick_filter_var = tk.StringVar()
        self._drag_press_item = None
        self._drag_press_xy = None
        self._dragging = False
        self._refresh_after_drag = False
        self._column_resize_job = None
        self._inline_editor = None
        self._inline_item = None
        self._inline_placeholder = False
        self.heading_labels = {"name": tr("Name"), "ext": tr("Ext"), "size": tr("Size"),
                               "modified": tr("Date Modified")}
        self.icons = ShellIconProvider()
        # Treeview stores Tcl image names, not Python references. Pin displayed
        # images independently of the bounded provider cache (and zoom changes).
        self._row_icons = {}
        self._vcs_statuses: dict[str, str] = {}
        self._vcs_path: Path | None = None
        self._vcs_requested_at = 0.0
        self._vcs_generation = 0
        self._vcs_loading = False
        self._vcs_results = queue.Queue()

        # Keep the command target visible even when the panel has no selected row.
        self.active_indicator = tk.Frame(self, height=3, background="#9aa7b3",
                                         highlightthickness=0)
        self.active_indicator.pack(fill="x", side="top")

        bar = ttk.Frame(self)
        bar.pack(fill="x", pady=(0, 3))
        self.drive = ttk.Combobox(bar, state="readonly", width=8, values=[str(p) for p in roots()])
        self.drive.pack(side="left")
        self.drive.bind("<<ComboboxSelected>>",
                        lambda _e: self.navigate_external(Path(self.drive.get())))
        self.up_button = ttk.Button(bar, text="↑", width=2, command=self.up)
        self.up_button.pack(side="left", padx=2)
        self._home_match = None
        self._home_images = {}
        self._automatic_home_prefixes = getattr(self.winfo_toplevel(), "home_prefixes", None)
        if self._automatic_home_prefixes is None:
            self._automatic_home_prefixes = discover_home_prefixes()
        self.home_button = ttk.Button(bar, width=2, command=self.go_home_prefix)
        self.home_button.pack(side="left")
        self.home_button.bind("<Button-3>", self.show_home_prefixes)
        self.home_button.bind("<Shift-F10>", self.show_home_prefixes)
        self.home_button._pfc_tooltip = ToolTip(self.home_button, self._home_tooltip, delay=700)
        self.path_var = tk.StringVar()
        self.view_mode_button = ttk.Button(bar, width=0, command=self.show_view_modes)
        self.view_mode_button.pack(side="right", padx=(4, 0))
        self.view_mode_button.bind('<Button-3>',lambda e:self.show_view_modes())
        self.view_mode_button.bind('<Shift-F10>',lambda e:self.show_view_modes())
        self.view_mode_button.bind('<KeyPress-Menu>',lambda e:self.show_view_modes())
        self.path_bar = PathBar(bar, self.path_var, self._breadcrumb_parts,
                                self._navigate_crumb, self._submit_path, self.focus_file_list)
        self.path_bar.pack(side="left", fill="x", expand=True, padx=(4, 0))
        self.path_entry = self.path_bar.entry
        self.path_entry.bind("<FocusIn>", lambda _e: self.on_activate(self), add="+")
        bar.bind("<Configure>", lambda _e: self._update_view_mode_button())
        ToolTip(self.view_mode_button, lambda: tr({"list": "List", "folder": "Folder tree",
                "file": "File tree"}[self.view_mode]), delay=700)
        self._update_view_mode_button()

        frame = ttk.Frame(self)
        frame.pack(fill="both", expand=True)
        self.tree = ttk.Treeview(frame, columns=self.columns, show="tree headings", selectmode="extended", style="Inactive.Treeview")
        self.tree.heading("#0", text=tr("Name") + " ▲", command=lambda: self.change_sort("name"))
        self.tree.column("#0", width=self.base_widths["name"], minwidth=120, stretch=True)
        for col in self.columns:
            marker = ""
            self.tree.heading(col, text=self.heading_labels[col] + marker, command=lambda c=col: self.change_sort(c))
            self.tree.column(col, width=self.base_widths[col], stretch=False, anchor="e" if col in ("size", "modified") else "w")
        scroll = ttk.Scrollbar(frame, orient="vertical", command=self.tree.yview)
        horizontal = ttk.Scrollbar(frame, orient="horizontal", command=self.tree.xview)
        def scrolled(bar, *args):
            changed = tuple(bar.get()) != tuple(float(value) for value in args)
            bar.set(*args)
            if changed and hasattr(self, "name_marquee"):
                self.name_marquee.request()
                self.size_units.request()
        self.tree.configure(yscrollcommand=lambda *args: scrolled(scroll, *args),
                            xscrollcommand=lambda *args: scrolled(horizontal, *args))
        self.tree.bind("<Configure>", lambda _event: self._schedule_column_autosize())
        horizontal.pack(side="bottom", fill="x")
        self.tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        self.tree.bind("<Double-1>", self.open_selected)
        self.tree.bind("<Return>", self.open_selected)
        self.tree.bind("<FocusIn>", lambda _e: self.on_activate(self))
        self.tree.bind("<ButtonPress-1>", self._drag_press, add="+")
        self.tree.bind("<B1-Motion>", self._drag_motion, add="+")
        self.tree.bind("<ButtonRelease-1>", self._drag_release, add="+")
        self.tree.bind("<ButtonRelease-3>", self._context_click)
        self.tree.bind("<Shift-F10>", self._context_keyboard)
        self.tree.bind("<KeyPress-Menu>", self._context_keyboard)
        self.tree.bind("<Prior>", lambda _event: self.page_selection(-1))
        self.tree.bind("<Next>", lambda _event: self.page_selection(1))
        self.tree.bind("<<TreeviewOpen>>", self._tree_open)
        self._name_tooltip = TreeItemToolTip(self.tree, self._tooltip_name, delay=3000)
        self.name_marquee = NameMarquee(self)
        self.size_units = SizeUnitCells(self)
        self.tree.tag_configure("PFC_DROP_TARGET", background="#8ec8f0", foreground="#102b3c")
        self.quick_filter_bar = ttk.Frame(self)
        ttk.Label(self.quick_filter_bar, text=tr("Quick Filter:")).pack(side="left")
        self.quick_filter_entry = ttk.Entry(self.quick_filter_bar, textvariable=self.quick_filter_var)
        self.quick_filter_entry.pack(side="left", fill="x", expand=True, padx=(4, 3))
        ttk.Button(self.quick_filter_bar, text="×", width=3, command=self.clear_quick_filter).pack(side="right")
        self.quick_filter_entry.bind("<Escape>", lambda _event: self.clear_quick_filter())
        self.quick_filter_entry.bind("<Return>", lambda _event: self.focus_file_list())
        self.quick_filter_var.trace_add("write", self._quick_filter_changed)
        self.status = ttk.Label(self, anchor="w")
        self.status.pack(fill="x", pady=(3, 0))
        self.quick_filter_bar.pack(fill="x", pady=(2, 0))
        install_button_tooltips(self)
        self.after(150, self._poll_vcs_results)
        self.navigate(self.path)
        try:
            self.shell_drop_target = ShellFileDropTarget(
                self.tree, self._shell_files_dropped, self._shell_virtual_files_dropped)
        except OSError:
            self.shell_drop_target = None

    def apply_language(self) -> None:
        self.heading_labels = {"name": tr("Name"), "ext": tr("Ext"), "size": tr("Size"),
                               "modified": tr("Date Modified")}
        for column in self.all_sort_columns:
            marker = (" ▼" if self.reverse else " ▲") if column == self.sort_column else ""
            self.tree.heading("#0" if column == "name" else column,
                              text=self.heading_labels[column] + marker)
        for child in self.quick_filter_bar.winfo_children():
            if isinstance(child, ttk.Label):
                child.configure(text=tr("Quick Filter:"))
                break
        self._update_view_mode_button()
        self.path_bar.redraw()
        self.refresh()

    def _update_view_mode_button(self) -> None:
        labels = {"list": "List", "folder": "Folder tree", "file": "File tree"}
        icons = {"list": "≡", "folder": "▸", "file": "☷"}
        compact = self.winfo_width() < tkfont.nametofont("TkDefaultFont").measure("M" * 55)
        em = tkfont.nametofont("TkDefaultFont").measure("M")
        self.drive.configure(width=3 if compact else 8)
        if self.winfo_width() < em * 30:
            self.drive.pack_forget()
        elif not self.drive.winfo_manager():
            self.drive.pack(side="left", before=self.up_button)
        # The icon represents hidden path text and must stay visible.
        if not self.home_button.winfo_manager():
            self.home_button.pack(side="left", after=self.up_button)
        self.view_mode_button.configure(text=(icons[self.view_mode] if compact else tr(labels[self.view_mode])) + " ▾")

    def show_view_modes(self) -> str:
        self.on_activate(self)
        if getattr(self, "_view_mode_menu", None) is not None:
            self._view_mode_menu.destroy()
        menu = tk.Menu(self, tearoff=False, font="TkMenuFont")
        self._view_mode_menu = menu
        palette = getattr(self.winfo_toplevel(), "palette", {})
        if palette:
            menu.configure(background=palette["menu"], foreground=palette["menu_text"],
                           activebackground=palette["menu_active"], activeforeground=palette["menu_active_text"])
        self._view_mode_selection = selected = tk.StringVar(value=self.view_mode)
        for mode, label in (("list", "List"), ("folder", "Folder tree"), ("file", "File tree")):
            menu.add_radiobutton(label=tr(label), value=mode, variable=selected,
                                 command=lambda m=mode: self.set_view_mode(m))
        try:
            menu.tk_popup(self.view_mode_button.winfo_rootx(),
                          self.view_mode_button.winfo_rooty() + self.view_mode_button.winfo_height())
        finally:
            menu.grab_release()
        return 'break'

    def set_view_mode(self, mode: str) -> None:
        if mode not in ("list", "folder", "file") or mode == self.view_mode:
            return
        selected = self.selected_paths()
        self.view_mode = mode
        self._update_view_mode_button()
        self.refresh()
        retained = []
        def collect(parent=""):
            for iid in self.tree.get_children(parent):
                tags = self.tree.item(iid, "tags")
                if tags and Path(tags[0]) in selected:
                    retained.append(iid)
                collect(iid)
        collect()
        if retained:
            self.tree.selection_set(retained)
            self.tree.focus(retained[0])
            self.tree.see(retained[0])
        self.focus_file_list()
        self.on_change()

    def cycle_view_mode(self) -> None:
        order = ("list", "folder", "file")
        self.set_view_mode(order[(order.index(self.view_mode) + 1) % len(order)])

    def _breadcrumb_parts(self):
        session = self.archive_session
        in_archive = session is not None and session.contains(self.path)
        if in_archive:
            parts = path_ancestors(session.archive_path.parent)
            parts.append((session.archive_path.name, session.root))
            relative = session.relative_path(self.path)
            target = session.root
            for name in relative.parts:
                target = target / name
                parts.append((name, target))
        else:
            parts = path_ancestors(self.path)
        owner = self.winfo_toplevel()
        prefix_location = session.archive_path.parent if in_archive else self.path
        self._home_match = match_home_prefix(prefix_location, self._automatic_home_prefixes,
                                             getattr(owner, "custom_home_prefixes", []))
        icon = self._home_match[1] if self._home_match else "root"
        size = prefix_icon_size(self)
        key = (icon, size)
        if key not in self._home_images:
            self._home_images[key] = prefix_icon(self, icon, size)
        self.home_button.configure(image=self._home_images[key])
        ink = getattr(owner, "palette", {}).get("text", "#34465a")
        parent_key = ("parent", size, ink)
        if parent_key not in self._home_images:
            self._home_images[parent_key] = prefix_icon(self, "parent", size, ink)
        self.up_button.configure(image=self._home_images[parent_key])
        if self._home_match:
            prefix = self._home_match[0]
            for index, (_label, target) in enumerate(parts):
                if target == prefix:
                    return parts[index+1:] or [(tr(PREFIX_ICONS[icon]), prefix)]
        return parts

    def _home_tooltip(self):
        prefix, icon = self._home_match or (self._home_root(), "root")
        label = tr(PREFIX_ICONS[icon]) if icon != "root" else tr("Root folder")
        return f"{label}\n{prefix}\n{tr('Right-click to configure folder prefixes.')}"

    def _home_root(self):
        # ZIPs retain the root of their real location, never the temp drive.
        session = self.archive_session
        location = session.archive_path if session is not None and session.contains(self.path) else self.path
        return Path(location.anchor)

    def go_home_prefix(self):
        self.on_activate(self)
        self.navigate_external(self._home_match[0] if self._home_match else self._home_root())
        self.focus_file_list()

    def show_home_prefixes(self, event=None):
        self.on_activate(self)
        owner = self.winfo_toplevel()
        if getattr(self, "_home_menu", None) is not None:
            self._home_menu.destroy()
        menu = self._home_menu = tk.Menu(self, tearoff=False, font="TkMenuFont")
        palette = getattr(owner, "palette", {})
        if palette:
            menu.configure(background=palette["menu"], foreground=palette["menu_text"],
                           activebackground=palette["menu_active"], activeforeground=palette["menu_active_text"])
        self._home_menu_images = {key: prefix_icon(self, key) for key in PREFIX_ICONS}
        for path, icon in self._automatic_home_prefixes:
            menu.add_command(label=f"{tr(PREFIX_ICONS[icon])} — {path}", image=self._home_menu_images[icon],
                             compound="left", command=lambda p=path: self._navigate_crumb(p))
        menu.add_separator()
        for index, item in enumerate(getattr(owner, "custom_home_prefixes", [])):
            path, icon = item["path"], item["icon"]
            menu.add_command(label=f"{index+1}. {tr(PREFIX_ICONS[icon])} — {path or tr('Not set')}",
                             image=self._home_menu_images[icon], compound="left",
                             command=(lambda p=path: self._navigate_crumb(Path(p))) if path else owner.edit_home_prefixes)
        if hasattr(owner, "edit_home_prefixes"):
            menu.add_separator()
            menu.add_command(label=tr("Custom folder prefixes") + "…", command=owner.edit_home_prefixes)
        try:
            menu.tk_popup(self.home_button.winfo_rootx(), self.home_button.winfo_rooty()+self.home_button.winfo_height())
        finally:
            menu.grab_release()
        return "break"

    def _navigate_crumb(self, target):
        self.on_activate(self)
        if self.archive_session is not None and self.archive_session.contains(target):
            self.navigate(target)
        else:
            self.navigate_external(target)
        self.focus_file_list()

    def _tree_values(self, path: Path, is_dir: bool, stat) -> tuple[str, str, str]:
        return ("" if is_dir else path.suffix[1:].upper(),
                "<DIR>" if is_dir else compact_file_size(stat.st_size),
                 self.format_modified(stat.st_mtime, path))

    def format_modified(self, timestamp, path):
        owner = self.winfo_toplevel()
        text = modified_text(timestamp, owner.date_order_var.get(), owner.time_style_var.get())
        self._date_values[str(path)] = timestamp
        return text

    def apply_column_settings(self):
        owner = self.winfo_toplevel()
        if self.mode != 'files' or self.view_mode == 'list':
            self.tree.configure(displaycolumns=tuple(c for c in self.columns if owner.column_visible_vars[c].get()))
        def update(parent=''):
            for iid in self.tree.get_children(parent):
                tags = self.tree.item(iid, 'tags')
                path = tags[0] if tags else ''
                if path in self._date_values:
                    self.tree.set(iid, 'modified', self.format_modified(self._date_values[path], path))
                update(iid)
        update()
        self._schedule_column_autosize()

    def _icon(self, path: Path, is_dir: bool):
        owner = self.winfo_toplevel()
        cloud = owner.cloud_status.get(path) if owner.onedrive_overlay_var.get() else None
        vcs = status_for(self._vcs_statuses, path) if owner.vcs_overlay_var.get() else None
        image = self.icons.get(path, is_dir, vcs, cloud)
        self._row_icons[str(path)] = image
        return image

    def _full_item_name(self, iid: str) -> str:
        tags = self.tree.item(iid, "tags")
        if not tags or tags[0] == "PFC_INLINE_PLACEHOLDER":
            return ""
        path = Path(tags[0])
        visible = path.name if path.is_dir() or self.show_extensions else path.stem
        if self.view_mode == "list":
            return f"[{visible}]" if path.is_dir() else visible
        current = str(self.tree.item(iid, "text"))
        prefix = "└─ " if current.startswith("└─ ") else "├─ " if current.startswith("├─ ") else ""
        return prefix + visible

    def _tooltip_name(self, iid: str) -> str:
        tags = self.tree.item(iid, 'tags')
        owner = self.winfo_toplevel()
        cloud = owner.cloud_status.get(tags[0]) if tags and owner.onedrive_overlay_var.get() else None
        if cloud:
            return (self._full_item_name(iid) + '\nOneDrive: ' + tr(CLOUD_LABELS[cloud])
                    + '\n' + tr(CLOUD_DETAILS[cloud]))
        if self.name_marquee.item == iid:
            return ""
        full = self._full_item_name(iid)
        return full if full and self.name_marquee.clipped(iid) else ""

    def _fit_visible_names(self) -> None:
        def fit(parent=""):
            for iid in self.tree.get_children(parent):
                full = self._full_item_name(iid)
                if full:
                    self.tree.item(iid, text=full)
                fit(iid)
        fit()
        self.name_marquee.request()
        self.size_units.request()

    def _request_vcs_statuses(self) -> None:
        if not self.winfo_toplevel().vcs_overlay_var.get():
            return
        if self.archive_session is not None:
            self._vcs_path = None; self._vcs_statuses = {}
            return
        now, path = time.monotonic(), self.path
        if self._vcs_loading and self._vcs_path == path:
            return
        if self._vcs_path == path and now - self._vcs_requested_at < 10.0:
            return
        if self._vcs_path != path:
            self._vcs_statuses = {}
        self._vcs_path = path; self._vcs_requested_at = now
        self._vcs_generation += 1
        self._vcs_loading = True
        generation = self._vcs_generation
        def load():
            self._vcs_results.put((generation, path, folder_statuses(path)))
        threading.Thread(target=load, name="PFC-VCS", daemon=True).start()

    def _poll_vcs_results(self) -> None:
        try:
            while True:
                generation, path, statuses = self._vcs_results.get_nowait()
                if generation == self._vcs_generation and path == self.path:
                    self._vcs_loading = False
                    previous = self._vcs_statuses
                    if statuses != previous:
                        self._vcs_statuses = statuses
                        self._apply_vcs_icons(previous)
        except queue.Empty:
            pass
        try:
            self.after(150, self._poll_vcs_results)
        except tk.TclError:
            pass

    def _apply_vcs_icons(self, previous: dict[str, str] | None = None) -> None:
        previous = previous or {}
        def apply(parent=""):
            for iid in self.tree.get_children(parent):
                tags = self.tree.item(iid, "tags")
                if tags and tags[0] != "PFC_INLINE_PLACEHOLDER":
                    path = Path(tags[0])
                    if status_for(previous, path) != status_for(self._vcs_statuses, path):
                        try: self.tree.item(iid, image=self._icon(path, path.is_dir()))
                        except OSError: pass
                apply(iid)
        apply()

    def _tree_label(self, path: Path, is_dir: bool, is_last: bool = False) -> str:
        visible = path.name if is_dir or self.show_extensions else path.stem
        return ("└─ " if is_last else "├─ ") + visible

    def _populate_tree_children(self, parent_iid: str, folder: Path) -> int:
        try:
            entries = [path for path in folder.iterdir()
                       if (self.show_hidden or not is_hidden(path)) and
                       (self.show_system or not is_system(path))]
        except OSError:
            return 0
        needle = self.quick_filter_var.get().strip().casefold()
        if needle:
            entries = [path for path in entries if needle in path.name.casefold()]
        if self.view_mode == "folder":
            entries = [path for path in entries if path.is_dir()]
        def sort_key(path: Path):
            try:
                stat = path.stat()
                values = {"name": path.name.casefold(), "ext": path.suffix.casefold(),
                          "size": stat.st_size, "modified": stat.st_mtime}
                return values[self.sort_column]
            except OSError:
                return path.name.casefold()
        entries.sort(key=sort_key, reverse=self.reverse)
        if not self.mix_sorting:
            entries.sort(key=lambda path: not path.is_dir())
        added = 0
        for index, path in enumerate(entries):
            try:
                stat, is_dir = path.stat(), path.is_dir()
                iid = self.tree.insert(parent_iid, "end",
                                       text=self._tree_label(path, is_dir,
                                                            index == len(entries) - 1),
                                       image=self._icon(path, is_dir),
                                       values=self._tree_values(path, is_dir, stat),
                                       tags=(str(path),))
                if is_dir:
                    self.tree.insert(iid, "end", text="", tags=())
                added += 1
            except OSError:
                continue
        return added

    def _tree_open(self, _event=None) -> None:
        if self.view_mode == "list":
            return
        iid = self.tree.focus()
        if not iid:
            return
        tags = self.tree.item(iid, "tags")
        children = self.tree.get_children(iid)
        if not tags or not children:
            return
        if all(not self.tree.item(child, "tags") for child in children):
            self.tree.delete(*children)
            self._populate_tree_children(iid, Path(tags[0]))
            self._schedule_column_autosize()

    def _expanded_tree_paths(self) -> set[str]:
        expanded = set()
        def collect(parent=""):
            for iid in self.tree.get_children(parent):
                tags = self.tree.item(iid, "tags")
                if tags and self.tree.item(iid, "open"):
                    expanded.add(tags[0]); collect(iid)
        collect()
        return expanded

    def _restore_tree_expansion(self, parent_iid: str, expanded: set[str]) -> None:
        for iid in self.tree.get_children(parent_iid):
            tags = self.tree.item(iid, "tags")
            if not tags or tags[0] not in expanded:
                continue
            children = self.tree.get_children(iid)
            if children and all(not self.tree.item(child, "tags") for child in children):
                self.tree.delete(*children)
                self._populate_tree_children(iid, Path(tags[0]))
            self.tree.item(iid, open=True)
            self._restore_tree_expansion(iid, expanded)

    def _shell_files_dropped(self, paths, x_root: int, y_root: int, move: bool) -> None:
        self.on_drag("external_drop", self, {
            "paths": list(paths), "x_root": x_root, "y_root": y_root, "move": move,
        })

    def _shell_virtual_files_dropped(self, paths, failures, x_root: int, y_root: int) -> None:
        self.on_drag("virtual_drop", self, {
            "paths": list(paths), "failures": list(failures),
            "x_root": x_root, "y_root": y_root,
        })

    def _drag_press(self, event):
        self.name_marquee.stop()
        region = self.tree.identify_region(event.x, event.y)
        iid = self.tree.identify_row(event.y)
        if not iid and region not in {"heading", "separator"}:
            selected = self.tree.selection()
            if selected:
                self.tree.selection_remove(*selected)
            self.tree.focus(""); self.tree.focus_set(); self.on_activate(self)
            self._drag_press_item = None; self._drag_press_xy = None
            return "break"
        if region not in {"tree", "cell"}:
            self._drag_press_item = None; self._drag_press_xy = None; return None
        # FocusIn is not guaranteed to fire when Tk preserves focus during a
        # multi-selection click.  Activate explicitly before any hotkey can run.
        self.on_activate(self)
        self._drag_press_item = iid
        self._drag_press_xy = (event.x_root, event.y_root)
        self._dragging = False
        if self._drag_press_item in self.tree.selection():
            self.tree.focus(self._drag_press_item); self.tree.focus_set()
            return "break"  # Preserve an existing multi-selection while beginning a drag.
        return None

    def _drag_motion(self, event):
        self.name_marquee.stop()
        if not self._drag_press_item or self._drag_press_xy is None:
            return None
        if not self._dragging:
            if abs(event.x_root - self._drag_press_xy[0]) < 6 and abs(event.y_root - self._drag_press_xy[1]) < 6:
                return None
            if self._drag_press_item not in self.tree.selection():
                self.tree.selection_set(self._drag_press_item)
            self._dragging = True
            self.on_drag("start", self, event)
        else:
            self.on_drag("motion", self, event)
        return "break"

    def _drag_release(self, event):
        was_dragging = self._dragging
        self._drag_press_item = None; self._drag_press_xy = None; self._dragging = False
        try:
            if was_dragging:
                self.on_drag("drop", self, event)
        finally:
            if self._refresh_after_drag:
                self._refresh_after_drag = False
                self.after_idle(self.refresh)
            self.name_marquee.request()
        return "break" if was_dragging else None

    def _dispatch_context(self, path, x_root, y_root):
        self.name_marquee.suspended = True
        self.name_marquee.stop()
        preference = getattr(self.winfo_toplevel(), "right_click_menu_var", None)
        handler = self.on_context if preference is not None and preference.get() == "pfc" else self.on_native_context
        try:
            handler(self, path, x_root, y_root)
        finally:
            self.name_marquee.suspended = False
            self.name_marquee.request()

    def _context_click(self, event):
        self.name_marquee.stop()
        if self.tree.identify_region(event.x, event.y) == 'heading':
            self.on_activate(self)
            number = int(self.tree.identify_column(event.x)[1:])
            visible = self.tree.cget('displaycolumns')
            column = 'name' if number == 0 else visible[number-1]
            self.winfo_toplevel().show_column_menu(column, event)
            return 'break'
        iid = self.tree.identify_row(event.y)
        if not iid:
            if self.tree.identify_region(event.x,event.y)=='separator':return 'break'
            self.tree.focus_set();self.on_activate(self)
            self.winfo_toplevel().show_panel_context_menu(self,event.x_root,event.y_root)
            return 'break'
        if iid not in self.tree.selection():
            self.tree.selection_set(iid)
        self.tree.focus(iid); self.tree.focus_set(); self.on_activate(self)
        tags = self.tree.item(iid, "tags")
        if tags:
            self._dispatch_context(Path(tags[0]), event.x_root, event.y_root)
        return "break"

    def _context_keyboard(self, _event=None):
        iid = self.tree.focus() or (self.tree.selection()[0] if self.tree.selection() else "")
        if not iid:
            self.tree.focus_set();self.on_activate(self)
            self.winfo_toplevel().show_panel_context_menu(self,self.tree.winfo_rootx()+20,
                                                        self.tree.winfo_rooty()+35)
            return "break"
        if iid not in self.tree.selection():
            self.tree.selection_set(iid)
        self.tree.focus(iid); self.tree.focus_set(); self.on_activate(self)
        tags, box = self.tree.item(iid, "tags"), self.tree.bbox(iid)
        if tags:
            x = self.tree.winfo_rootx() + (box[0] + 20 if box else 20)
            y = self.tree.winfo_rooty() + (box[1] + box[3] if box else 20)
            self._dispatch_context(Path(tags[0]), x, y)
        return "break"

    def page_selection(self, direction: int) -> str:
        """Move a full visible page while keeping focus and selection together."""
        children = list(self.tree.get_children())
        if not children:
            return "break"
        current = self.tree.focus() or (self.tree.selection()[0] if self.tree.selection() else children[0])
        try:
            index = children.index(current)
        except ValueError:
            index = 0
        row_height = max(1, int(ttk.Style(self).lookup(self.tree.cget("style"), "rowheight") or 24))
        page = max(1, self.tree.winfo_height() // row_height - 1)
        target = children[max(0, min(len(children) - 1, index + direction * page))]
        self.tree.selection_set(target)
        self.tree.focus(target)
        self.tree.see(target)
        self.tree.focus_set()
        self.on_activate(self)
        return "break"

    def begin_inline_name(self, initial_name: str, commit,
                          path: Path | None = None, placeholder: bool = False) -> bool:
        self.cancel_inline_name()
        iid = ""
        if path is not None:
            normalized = os.path.normcase(str(path))
            for candidate in self.tree.get_children():
                tags = self.tree.item(candidate, "tags")
                if tags and os.path.normcase(tags[0]) == normalized:
                    iid = candidate
                    break
        if not iid and placeholder:
            iid = self.tree.insert("", "end", text=f"[{initial_name}]",
                                   image=self.icons.blank, values=("", "<DIR>", ""),
                                   tags=("PFC_INLINE_PLACEHOLDER",))
        if not iid:
            return False
        self.tree.see(iid); self.tree.update_idletasks()
        bounds = self.tree.bbox(iid, "#0")
        if not bounds:
            if placeholder: self.tree.delete(iid)
            return False
        x, y, width, height = bounds
        icon_gap = self.icons.size + self.icons.text_gap + 2
        editor = ttk.Entry(self.tree)
        editor.insert(0, initial_name)
        editor.place(x=x + icon_gap, y=y, width=max(80, width - icon_gap), height=height)
        self._inline_editor, self._inline_item = editor, iid
        self._inline_placeholder = placeholder
        editor.bind("<Return>", lambda _event: self._finish_inline_name(True, commit))
        editor.bind("<Escape>", lambda _event: self._finish_inline_name(False, commit))
        editor.bind("<FocusOut>", lambda _event: self.after_idle(
            lambda: self._finish_inline_name(True, commit)))
        editor.focus_force()
        if path is not None and path.is_file() and path.suffix:
            editor.selection_range(0, len(path.stem))
            editor.icursor(len(path.stem))
        else:
            editor.selection_range(0, "end")
        return True

    def _finish_inline_name(self, accepted: bool, commit) -> str:
        editor, iid = self._inline_editor, self._inline_item
        if editor is None:
            return "break"
        name = editor.get().strip()
        placeholder = self._inline_placeholder
        self._inline_editor = self._inline_item = None
        self._inline_placeholder = False
        try: editor.destroy()
        except tk.TclError: pass
        if not accepted:
            if placeholder and iid and self.tree.exists(iid): self.tree.delete(iid)
            self.focus_file_list()
            return "break"
        result = commit(name)
        if placeholder and iid and self.tree.exists(iid): self.tree.delete(iid)
        if isinstance(result, Path):
            self.refresh(); self.select_path(result)
        self.focus_file_list()
        return "break"

    def cancel_inline_name(self) -> None:
        if self._inline_editor is not None:
            self._finish_inline_name(False, lambda _name: None)

    def navigate(self, path: Path, bypass_lock: bool = False) -> bool:
        try:
            path = path.expanduser().resolve()
            if not path.is_dir():
                raise NotADirectoryError(path)
            if not bypass_lock and self.lock_mode == "locked" and path != self.path:
                self.on_locked_navigation(path)
                return False
            previous = self.path
            focused = self.tree.focus()
            if not focused and self.tree.selection():
                focused = self.tree.selection()[0]
            if focused:
                tags = self.tree.item(focused, "tags")
                if tags:
                    selected = Path(tags[0])
                    if selected.parent == previous:
                        self.folder_selections[previous] = selected
            if path != self.path:
                self.history.append(self.path)
                self._reset_view_on_refresh = True
            self.path = path
            self.mode = "files"
            if self.archive_session is not None and self.archive_session.contains(path):
                relative = self.archive_session.relative_path(path)
                self.display_title = (relative.name if relative.parts
                                      else self.archive_session.archive_path.name)
            else:
                self.display_title = path.name or str(path)
            self.path_bar.set_location(self.display_path())
            self.drive.set(path.anchor or os.sep)
            self.refresh()
            self.on_change()
            return True
        except OSError as exc:
            self.path_var.set(str(self.path))
            messagebox.showerror(tr("Cannot open folder"), str(exc))
            return False

    def up(self) -> None:
        if self.archive_session is not None and self.path == self.archive_session.root:
            if self.on_exit_archive(self):
                return
        self.navigate(self.path.parent)

    def navigate_external(self, path: Path) -> bool:
        if self.lock_mode == "locked" and path != self.path:
            self.on_locked_navigation(path)
            return False
        if self.archive_session is not None:
            self.on_exit_archive(self)
            if self.archive_session is not None:
                return False
        return self.navigate(path)

    def display_path(self) -> str:
        if self.archive_session is not None and self.archive_session.contains(self.path):
            return self.archive_session.display_path(self.path)
        return str(self.path)

    def logical_path(self, path: Path) -> str:
        if self.archive_session is not None and self.archive_session.contains(path):
            return self.archive_session.display_path(path)
        return str(path.resolve())

    def persistent_path(self) -> Path:
        if self.archive_session is not None:
            return self.archive_session.archive_path.parent
        return self.path

    def navigate_from_entry(self, _event=None) -> str:
        self._submit_path()
        return "break"

    def _submit_path(self) -> bool:
        raw = self.path_var.get().strip().strip('"')
        if not raw:
            return False
        if self.archive_session is not None:
            archive_text = str(self.archive_session.archive_path)
            normalized = os.path.normcase(raw)
            if normalized == os.path.normcase(archive_text) or normalized.startswith(os.path.normcase(archive_text + os.sep)):
                relative = raw[len(archive_text):].lstrip("\\/")
                target = (self.archive_session.root / relative).resolve()
                if not self.archive_session.contains(target):
                    messagebox.showerror(tr("Cannot open folder"), raw)
                    return False
                return self.locate_from_path(target)
        target = Path(raw).expanduser()
        if not target.exists():
            messagebox.showerror(tr("Cannot open folder"), str(target))
            return False
        if self.lock_mode == "locked" and navigation_destination(target)[0] != self.path:
            self.on_locked_navigation(target)
            self.path_var.set(self.display_path())
            return True
        if self.archive_session is not None:
            self.on_exit_archive(self)
            if self.archive_session is not None:
                return False
        return self.locate_from_path(target)

    def locate_from_path(self, typed: Path) -> bool:
        """A path-bar file is a location request, never an open/run request."""
        folder, selected_file = navigation_destination(typed)
        if self.lock_mode == "locked" and folder != self.path:
            self.on_locked_navigation(typed)
            self.path_var.set(self.display_path())
            return True
        if selected_file is not None:
            # An explicit location takes precedence over a filter hiding it.
            self.quick_filter_var.set("")
            self.view_mode = "list"
            self._update_view_mode_button()
        if self.navigate(folder):
            if selected_file is not None:
                self.select_path(selected_file)
            self.focus_file_list()
            return True
        return False

    def change_sort(self, column: str) -> None:
        self.reverse = not self.reverse if self.sort_column == column else False
        self.sort_column = column
        for col in self.all_sort_columns:
            marker = (" ▲" if not self.reverse else " ▼") if col == self.sort_column else ""
            target = "#0" if col == "name" else col
            self.tree.heading(target, text=self.heading_labels[col] + marker)
        self.refresh()
        self.on_change()

    def refresh(self) -> None:
        if self._inline_editor is not None:
            return
        # Preserve Treeview IDs from mouse-down through drop. A filesystem
        # notification (including a Git working-tree change) can arrive before
        # the first motion, while _dragging is still False.
        if self._drag_press_item is not None:
            self._refresh_after_drag = True
            return
        self._refresh_after_drag = False
        self.name_marquee.stop()
        self.size_units.hide()
        reset_view = getattr(self, "_reset_view_on_refresh", False)
        self._reset_view_on_refresh = False
        if self.mode == "files" and self.view_mode != "list":
            self.tree.configure(show="tree", displaycolumns=())
        else:
            owner = self.winfo_toplevel()
            self.tree.configure(show="tree headings", displaycolumns=tuple(
                c for c in self.columns if owner.column_visible_vars[c].get()))
        selected = {self.tree.item(i, "tags")[0] for i in self.tree.selection() if self.tree.item(i, "tags")}
        focused_tags = self.tree.item(self.tree.focus(), "tags") if self.tree.focus() else ()
        focused_path = focused_tags[0] if focused_tags and not reset_view else None
        expanded = self._expanded_tree_paths() if self.view_mode != "list" else set()
        scroll_position = self.tree.yview()[0] if self.tree.get_children() else 0.0
        if reset_view:
            selected, expanded, scroll_position = set(), set(), 0.0
        self.tree.delete(*self.tree.get_children())
        self._row_icons.clear()
        self._date_values.clear()
        try:
            self._request_vcs_statuses()
            if self.mode == "files" and self.view_mode != "list":
                visible_entries = [p for p in self.path.iterdir()
                                   if (self.show_hidden or not is_hidden(p)) and
                                   (self.show_system or not is_system(p))]
                self._signature = self.signature_for(visible_entries)
                root_stat = self.path.stat()
                root_label = self.path.name or str(self.path)
                root_iid = self.tree.insert("", "end", text=root_label,
                                            image=self._icon(self.path, True),
                                            values=self._tree_values(self.path, True, root_stat),
                                            tags=(str(self.path),), open=True)
                count = self._populate_tree_children(root_iid, self.path)
                self._restore_tree_expansion(root_iid, expanded)
                mode_label = tr("Folder Tree") if self.view_mode == "folder" else tr("File Tree")
                self.status.configure(text=tr("{mode} — {count} items", mode=mode_label,
                                              count=count))
                selected_iids = []
                def restore_selection(parent=""):
                    for iid in self.tree.get_children(parent):
                        tags = self.tree.item(iid, "tags")
                        if tags and tags[0] in selected:
                            selected_iids.append(iid)
                        restore_selection(iid)
                restore_selection()
                target_iids = selected_iids or [root_iid]
                self.tree.selection_set(target_iids); self.tree.focus(target_iids[0])
                for target in target_iids:
                    if self.tree.item(target, "tags")[0] == focused_path:
                        self.tree.focus(target)
                        break
                self.tree.yview_moveto(scroll_position)
                self._schedule_column_autosize()
                return
            entries = [p for p in self.path.iterdir()
                       if (self.show_hidden or not is_hidden(p)) and (self.show_system or not is_system(p))]
            self._signature = self.signature_for(entries)
            needle = self.quick_filter_var.get().strip().casefold()
            if needle:
                entries = [path for path in entries if needle in path.name.casefold()]
            def key(p: Path):
                try:
                    stat = p.stat()
                    values = {"name": p.name.lower(), "ext": p.suffix.lower(), "size": stat.st_size,
                              "modified": stat.st_mtime}
                    return values[self.sort_column]
                except OSError:
                    return p.name.lower()
            entries.sort(key=key, reverse=self.reverse)
            if not self.mix_sorting:
                entries.sort(key=lambda path: not path.is_dir())
            total = 0
            for p in entries:
                try:
                    stat = p.stat()
                    is_dir = p.is_dir()
                    total += 0 if is_dir else stat.st_size
                    visible_name = p.name if is_dir or self.show_extensions else p.stem
                    name = f"[{visible_name}]" if is_dir else visible_name
                    values = ("" if is_dir else p.suffix[1:].upper(),
                              "<DIR>" if is_dir else compact_file_size(stat.st_size),
                              self.format_modified(stat.st_mtime, p))
                    iid = self.tree.insert("", "end", text=name, image=self._icon(p, is_dir), values=values, tags=(str(p),))
                    if str(p) in selected:
                        self.tree.selection_add(iid)
                        if str(p) == focused_path:
                            self.tree.focus(iid)
                except OSError:
                    continue
            filter_status = tr(" — filter: {filter}", filter=self.quick_filter_var.get().strip()) if needle else ""
            self.status.configure(text=tr("{count} items   {size}", count=len(entries),
                                          size=format_size(total)) + filter_status)
            current = self.tree.selection()
            children = self.tree.get_children()
            if not current and children:
                self.tree.selection_set(children[0])
                self.tree.focus(children[0])
                self.tree.see(children[0])
                self.tree.yview_moveto(0)
            elif children:
                if not self.tree.focus() and current:
                    self.tree.focus(current[0])
                self.tree.yview_moveto(scroll_position)
            self._schedule_column_autosize()
        except OSError as exc:
            messagebox.showerror(tr("Cannot read folder"), str(exc))

    def _schedule_column_autosize(self) -> None:
        if self._column_resize_job is not None:
            try:
                self.after_cancel(self._column_resize_job)
            except tk.TclError:
                pass
        self._column_resize_job = self.after_idle(self._autosize_columns)

    def _autosize_columns(self) -> None:
        """Fit detail fields to visible data and give all remaining width to Name."""
        self._column_resize_job = None
        if not self.tree.winfo_exists():
            return
        font = tkfont.nametofont("TkDefaultFont")
        padding = max(18, font.measure("MM"))
        self.size_units.sync_font()
        ext_width = extension_column_width(font.measure)
        children = self.tree.get_children()
        fixed_total = 0
        for value_index, column in enumerate(self.columns):
            if column not in self.tree.cget('displaycolumns'):
                continue
            if column == "ext":
                self.tree.column(column, width=ext_width, minwidth=ext_width, stretch=False)
                fixed_total += ext_width
                continue
            cell_padding = max(8, font.measure(" ") * 2) if column == "size" else padding
            measure = self.size_units.measure if column == "size" else font.measure
            heading_width = font.measure(str(self.tree.heading(column, "text"))) + cell_padding
            measured = heading_width
            for iid in children:
                values = self.tree.item(iid, "values")
                if value_index < len(values):
                    measured = max(measured, measure(str(values[value_index])) + cell_padding)
            minimum, maximum = (heading_width, measured)
            maximum = max(maximum, heading_width)
            width = max(minimum, min(measured, maximum))
            self.tree.column(column, width=width, minwidth=minimum, stretch=False)
            fixed_total += width
        available = max(1, self.tree.winfo_width() - 4)
        self.tree.column("#0", width=max(120, available - fixed_total), minwidth=120,
                         stretch=True)
        self._fit_visible_names()

    @staticmethod
    def signature_for(entries) -> tuple:
        signature = []
        for path in entries:
            try:
                stat = path.stat()
                signature.append((path.name, stat.st_size, stat.st_mtime_ns, stat.st_mode))
            except OSError:
                signature.append((path.name, None, None, None))
        return tuple(sorted(signature))

    def refresh_if_changed(self) -> bool:
        if self.mode != "files" or self._inline_editor is not None:
            return False
        self._request_vcs_statuses()
        try:
            entries = [p for p in self.path.iterdir()
                       if (self.show_hidden or not is_hidden(p)) and (self.show_system or not is_system(p))]
            signature = self.signature_for(entries)
        except OSError:
            return False
        if signature == self._signature:
            return False
        self.refresh()
        return True

    def selected_paths(self) -> list[Path]:
        result = []
        for iid in self.tree.selection():
            tags = self.tree.item(iid, "tags")
            if tags:
                result.append(Path(tags[0]))
        return result

    def select_path(self, path: Path) -> bool:
        for iid in self.tree.get_children():
            tags = self.tree.item(iid, "tags")
            if tags and Path(tags[0]) == path:
                self.tree.selection_set(iid); self.tree.focus(iid); self.tree.see(iid)
                return True
        return False

    def focus_file_list(self) -> None:
        children = self.tree.get_children()
        selected = self.tree.selection()
        target = selected[0] if selected else (children[0] if children else None)
        if target is not None:
            if not selected:
                self.tree.selection_set(target)
            self.tree.focus(target)
            self.tree.see(target)
        self.tree.focus_set()

    def _quick_filter_changed(self, *_args) -> None:
        if self.mode == "files":
            self.refresh()
            self.on_change()

    def set_quick_filter(self, value: str) -> None:
        self.quick_filter_var.set(value)

    def toggle_quick_filter(self) -> str:
        if self.mode != "files":
            self.mode = "files"; self.path_bar.set_location(self.display_path()); self.refresh()
        self.quick_filter_entry.focus_set()
        self.quick_filter_entry.selection_range(0, "end")
        return "break"

    def clear_quick_filter(self) -> str:
        self.quick_filter_var.set("")
        self.focus_file_list()
        self.on_change()
        return "break"

    def open_selected(self, _event=None) -> None:
        items = self.selected_paths()
        if not items:
            return
        item = items[0]
        if item.is_dir():
            if self.view_mode == "list":
                self.navigate(item)
            else:
                iid = self.tree.focus() or self.tree.selection()[0]
                opening = not bool(self.tree.item(iid, "open"))
                self.tree.item(iid, open=opening)
                if opening:
                    self._tree_open()
        elif self.on_open_file(self, item):
            return
        else:
            try:
                os.startfile(item) if os.name == "nt" else subprocess.Popen(["xdg-open", str(item)])
            except OSError as exc:
                messagebox.showerror(tr("Cannot open file"), str(exc))

    def show_preview(self, item: Path) -> None:
        self.mode = "preview"
        self.display_title = item.name
        self.tree.delete(*self.tree.get_children())
        self._row_icons.clear()
        self.path_bar.set_location(f"[Preview] {item}")
        try:
            stat = item.stat()
            details = [
                f"Name: {item.name}",
                f"Path: {item}",
                f"Size: {format_size(stat.st_size)}",
                f"Modified: {datetime.fromtimestamp(stat.st_mtime):%Y-%m-%d %H:%M:%S}",
                "",
            ]
            if item.is_dir():
                details.append("Folder preview: press Right to enter it.")
            elif item.suffix.lower() in {".txt", ".md", ".csv", ".json", ".xml", ".log", ".py", ".ini", ".yaml", ".yml"}:
                with item.open("r", encoding="utf-8", errors="replace") as stream:
                    details.extend(line.rstrip("\r\n") for _, line in zip(range(300), stream))
            else:
                details.append("Binary file: metadata preview only.")
            for line in details:
                self.tree.insert("", "end", text=line, values=("", "", ""))
            self.status.configure(text=f"Previewing {item.name}")
            self.on_change()
        except OSError as exc:
            messagebox.showerror(tr("Preview failed"), str(exc))

    def search(self, query: str) -> None:
        self.mode = "search"
        self.display_title = f"Search: {query}"
        self.tree.delete(*self.tree.get_children())
        self._row_icons.clear()
        self._date_values.clear()
        self.path_bar.set_location(f"[Search] {query} in {self.path}")
        query = query.casefold()
        count = 0
        try:
            for item in self.path.rglob("*"):
                if query not in item.name.casefold():
                    continue
                try:
                    stat = item.stat()
                    is_dir = item.is_dir()
                    relative = item.relative_to(self.path)
                    display = str(relative if is_dir or self.show_extensions else relative.with_name(item.stem))
                    self.tree.insert("", "end", text=display, image=self._icon(item, is_dir), values=(
                        "" if is_dir else item.suffix[1:].upper(),
                        "<DIR>" if is_dir else compact_file_size(stat.st_size),
                        self.format_modified(stat.st_mtime, item)),
                        tags=(str(item),))
                    count += 1
                    if count >= 2000:
                        break
                except OSError:
                    continue
            self.status.configure(text=f"{count} match(es)" + (" (limited to 2000)" if count == 2000 else ""))
            self.on_change()
        except OSError as exc:
            messagebox.showerror(tr("Search failed"), str(exc))

    def show_file_listing(self, paths, title: str) -> None:
        """Show arbitrary search results as an actionable temporary panel tab."""
        self.mode = "search_results"
        self.display_title = title
        self.path_bar.set_location(f"[{title}]")
        self.tree.delete(*self.tree.get_children())
        self._row_icons.clear()
        self._date_values.clear()
        total = 0
        for item in paths:
            path = Path(item)
            try:
                stat, is_dir = path.stat(), path.is_dir()
                total += 0 if is_dir else stat.st_size
                self.tree.insert("", "end", text=f"[{path.name}]" if is_dir else path.name,
                                 image=self._icon(path, is_dir),
                                 values=("" if is_dir else path.suffix[1:].upper(),
                                         "<DIR>" if is_dir else compact_file_size(stat.st_size),
                                         self.format_modified(stat.st_mtime, path)),
                                 tags=(str(path),))
            except OSError:
                continue
        self.status.configure(text=tr("{count} items   {size}",
                                      count=len(self.tree.get_children()), size=format_size(total)))
        children = self.tree.get_children()
        if children:
            self.tree.selection_set(children[0]); self.tree.focus(children[0]); self.tree.see(children[0])
        self._schedule_column_autosize(); self.on_change(); self.focus_file_list()

    def toggle_hidden(self) -> None:
        self.show_hidden = not self.show_hidden
        self.refresh()
        self.on_change()

    def toggle_system(self) -> None:
        self.show_system = not self.show_system
        self.refresh()
        self.on_change()

    def set_active_appearance(self, active: bool, palette=None) -> None:
        self.tree.configure(style="Active.Treeview" if active else "Inactive.Treeview")
        colors = palette or {}
        self.active_indicator.configure(
            background=colors.get("selection", "#0078d4") if active
            else colors.get("border", "#9aa7b3"))
        self.name_marquee.request()
        self.size_units.request()

    def apply_scale(self, scale: float) -> None:
        self.active_indicator.configure(height=max(2, round(3 * scale)))
        linespace = tkfont.nametofont("TkDefaultFont").metrics("linespace")
        icon_size = max(16, round(scaled_tree_row_height(linespace, scale) * .9))
        if self.icons.size != icon_size:
            self.icons = ShellIconProvider(icon_size)
        self.refresh()
        self._schedule_column_autosize()


class PaneTabs(ChamferNotebook):
    def __init__(self, master: tk.Misc, on_activate, on_change=lambda: None, initial_paths=None,
                 color_for=lambda _path: "default", on_tab_color=lambda _path, _color: None,
                 on_drag=lambda _action, _pane, _event: None,
                 on_context=lambda _pane, _path, _x, _y: None,
                 on_native_context=lambda _pane, _path, _x, _y: None,
                 on_open_file=lambda _pane, _path: False,
                 on_exit_archive=lambda _pane: False,
                 on_close_archive=lambda _pane: None,
                 on_selection=lambda: None,
                 on_tab_drag=lambda _action, _tabs, _pane, _event: False,
                 tab_style="right_skirt", on_open_folder=None) -> None:
        self.on_open_folder = on_open_folder
        self.color_for = color_for
        self.on_tab_color = on_tab_color
        self.on_drag = on_drag
        self.on_context = on_context
        self.on_native_context = on_native_context
        self.on_open_file = on_open_file
        self.on_exit_archive = on_exit_archive
        self.on_close_archive = on_close_archive
        self.on_selection = on_selection
        self.scale = 1.0
        super().__init__(master, on_color_changed=self._color_changed,
                         on_lock_changed=self._lock_changed,
                         on_tabs_reordered=self._tabs_reordered,
                         on_tab_drag=on_tab_drag, tab_style=tab_style)
        self.on_activate = on_activate
        self.on_change = on_change
        self.bind("<<NotebookTabChanged>>", lambda _e: self._tab_changed())
        for path in initial_paths or [Path.home()]:
            self.add_tab(path, notify=False)

    def add_tab(self, path: Path, notify: bool = True, position: int | None = None) -> FilePane:
        if position is None:
            position = self.index(self.select()) + 1 if self.tabs() else 0
        pane = FilePane(self, self.on_activate, on_drag=self.on_drag,
                        on_context=self.on_context, on_open_file=self.on_open_file,
                        on_native_context=self.on_native_context,
                        on_exit_archive=self.on_exit_archive)
        pane.tree.bind("<<TreeviewSelect>>", lambda _event: self.on_selection(), add="+")
        pane.on_change = lambda source=pane: self._pane_changed(source)
        pane.on_locked_navigation = lambda target, source=pane: (
            self.on_open_folder(source, target) if self.on_open_folder else self.add_tab(target))
        pane.navigate(path)
        pane.apply_scale(self.scale)
        self.add(pane, text=path.name or str(path), color="default", position=position)
        self.select(pane)
        pane.tree.focus_set()
        if notify:
            self.on_change()
        return pane

    def apply_scale(self, scale: float) -> None:
        self.scale = scale
        for pane in self.panes():
            pane.apply_scale(scale)

    def _pane_changed(self, pane: FilePane) -> None:
        if not self.tabs():
            self.on_change()
            return
        try:
            self.tab(pane, text=pane.display_title)
        except (tk.TclError, AttributeError):
            pass
        self.on_change()

    def _tab_changed(self) -> None:
        try:
            pane = self.current()
            self.on_activate(pane)
            self.after_idle(pane.focus_file_list)
        except tk.TclError:
            return
        self.on_change()

    def select(self, tab=None):
        if tab is None:
            return super().select()
        previous = self._selected
        result = super().select(tab)
        if previous is not None and previous is not self._selected:
            if previous.lock_mode == "reset" and previous.locked_path is not None:
                previous.navigate(previous.locked_path, bypass_lock=True)
        return result

    def current(self) -> FilePane:
        return self.nametowidget(self.select())

    def close_current(self) -> None:
        if len(self.tabs()) > 1:
            pane = self.current()
            self.forget(pane)
            self.on_close_archive(pane)
            pane.destroy()
            self.on_change()

    def panes(self) -> list[FilePane]:
        return [self.nametowidget(tab) for tab in self.tabs()]

    def _color_changed(self, pane, color) -> None:
        self.on_change()

    def _lock_changed(self, pane, mode) -> None:
        pane.lock_mode = mode
        pane.locked_path = None if mode == "unlocked" else pane.path
        self.on_change()

    def _tabs_reordered(self) -> None:
        self.on_change()


class ConflictDialog(tk.Toplevel):
    def __init__(self, parent, source: Path, target: Path) -> None:
        super().__init__(parent)
        self.result = ("cancel", False)
        self.apply_all = tk.BooleanVar(value=False)
        self.title(tr("File conflict")); self.resizable(False, False); self.transient(parent)
        body = ttk.Frame(self, padding=12); body.pack(fill="both", expand=True)
        ttk.Label(body, text=tr("An item with the same name already exists."),
                  font=tkfont.nametofont("TkHeadingFont")).pack(anchor="w", pady=(0, 8))
        ttk.Label(body, text=f"{tr('Source')}: {source}\n{tr('Destination')}: {target}", justify="left",
                  wraplength=720).pack(anchor="w")
        ttk.Checkbutton(body, text=tr("Apply this choice to all remaining conflicts"),
                        variable=self.apply_all).pack(anchor="w", pady=(12, 8))
        buttons = ttk.Frame(body); buttons.pack(fill="x")
        first_button = None
        for text, action in (("Replace existing", "replace"), ("Skip", "skip"),
                             ("Keep both", "keep_both"), ("Cancel", "cancel")):
            button = ttk.Button(buttons, text=tr(text), command=lambda value=action: self.choose(value))
            button.pack(side="left", padx=3)
            if first_button is None: first_button = button
        self.bind("<Escape>", lambda _event: self.choose("cancel"))
        self.protocol("WM_DELETE_WINDOW", lambda: self.choose("cancel"))
        self.update_idletasks()
        self.geometry(f"+{parent.winfo_rootx() + 60}+{parent.winfo_rooty() + 80}")
        self.grab_set(); self.lift(); self.focus_force()
        if first_button is not None: first_button.focus_set()

    def choose(self, action: str) -> None:
        self.result = (action, self.apply_all.get() if action != "cancel" else False)
        self.destroy()

    @classmethod
    def ask(cls, parent, source: Path, target: Path) -> tuple[str, bool]:
        dialog = cls(parent, source, target)
        parent.wait_window(dialog)
        return dialog.result


