    def _settings_are_open(self):
        dialog=getattr(self,'settings_window',None)
        return dialog is not None and dialog.winfo_exists()

    def show_vcs_actions(self):
        return self.vcs_actions.show()

    def _dispatch_global_hotkey(self, command):
        # Native combobox popdowns have their own toplevel: guarding only the
        # Settings toplevel binding does not protect the background file list.
        try:
            modal = self.grab_current()
        except (KeyError, tk.TclError):
            modal = True
        return 'break' if self._settings_are_open() or modal else command()

    def show_command_palette(self):
        if self._settings_are_open(): return 'break'
        commands = []
        for label, category, key, aliases, callback in (
            ('Preview', 'Files', 'F3', 'preview 預覽 预览', self.preview),
            ('Search', 'Files', 'F4', 'find 搜尋 搜索 搜寻', self.search),
            ('Compare', 'Files', 'F9', 'diff compare 比較 比较', self.compare_selected),
            ('Saved comparisons', 'Workflows', '', 'session compare 比較 工作階段 比较 会话', self.show_saved_comparisons),
            ('Workspaces', 'Workflows', '', 'workspace project tabs 工作區 工作区 專案 项目', lambda: show_workspaces(self)),
            ('Restore previous workspace', 'Workflows', '', 'undo workspace 復原 還原 恢复', self.restore_previous_workspace),
            ('New Tab', 'Go', 'Ctrl+Up', 'tab 分頁 标签', self.new_tab),
            ('Parent Folder', 'Go', 'Left', 'parent folder 上層 上层 目錄 目录', self.parent_folder),
            ('Quick Filter', 'Files', 'Ctrl+Y', 'filter 篩選 筛选', lambda: self.panes()[0].toggle_quick_filter()),
            ('Refresh', 'Files', 'Ctrl+R', 'reload 刷新 重新整理', self.refresh),
            ('Rename', 'Files', 'F2', 'rename multi 批次 改名 重命名', self.rename),
            ('Folder Space Analyzer', 'Tools', '', 'disk space 磁碟 磁盘 容量', self.show_space_analyzer),
            ('Copy Paths', 'Files', 'F11', 'copy path 路徑 路径', self.copy_paths),
            ('Check Update', 'Help', '', 'update 更新 升級 升级', self.check_update),
            ('Help', 'Help', 'F1', 'help 幫助 帮助', self.show_help),
        ):
            commands.append((tr(label), tr(category), key, label+' '+aliases, callback))
        from_specs = preference_specs(self)
        for key, category, group, label, choices, method in from_specs:
            commands.append((tr(label), tr(dict(SETTINGS_CATEGORIES)[category]), '',
                             label+' '+key+' '+tr(group), lambda c=category: self.show_settings(c)))
        CommandPalette(self, commands)
        return 'break'

    def show_saved_comparisons(self):
        if self.compare_window is None or not self.compare_window.winfo_exists():
            self.compare_window = CompareWindow(self, self.config_data, self.save_config, self.execute_sync_plans)
            self.compare_window.notebook.set_style(self.tab_style_var.get())
        self.compare_window.apply_scale(self._font_scales.get(self.font_size_var.get(), 1.0))
        self.compare_window.saved_comparisons()

    def show_workspace_picker(self):
        return show_workspaces(self)

    def restore_previous_workspace(self):
        records = WorkflowRecords(self.config_data, 'workspace_undo').read()
        if records:
            try: restore_workspace(self, records[0]['data'])
            except (OSError, ValueError) as exc: messagebox.showerror(tr('Workspaces'), str(exc), parent=self)
        else:
            messagebox.showinfo(tr('Workspaces'), tr('No previous workspace is saved yet.'), parent=self)

    def _install_priority_hotkeys(self, hotkeys, commands) -> None:
        """Run tab navigation before Tk widget/class bindings can consume Tab."""
        tag = f"PFCKeyboard{id(self)}"
        for name in ("switch_panel", "next_tab", "previous_tab", "enter_folder", "parent_folder"):
            self.bind_class(tag, hotkeys[name], lambda _event, fn=commands[name]: fn())
        self.bind_class(tag, hotkeys["select_previous"],
                        lambda event: None if event.state & 0x5 else self.move_selection(-1))
        self.bind_class(tag, hotkeys["select_next"],
                        lambda event: None if event.state & 0x5 else self.move_selection(1))
        self.bind_class(tag, hotkeys["permanent_delete"],
                        lambda _event: (commands["permanent_delete"](), "break")[1])

        def prepend(widget):
            tags = widget.bindtags()
            if tag not in tags:
                widget.bindtags((tag, *tags))
            for child in widget.winfo_children():
                prepend(child)

        prepend(self)

    @staticmethod
    def _find_ini_path() -> Path:
        executable = Path(sys.argv[0]).resolve()
        if executable.name.casefold() == "pfc.py":
            return executable.with_name("pfc.ini")
        return Path(__file__).resolve().parents[1] / "pfc.ini"

    def _load_navigation_paths(self, key: str) -> list[Path]:
        try:
            values = json.loads(self.config_data.get("navigation", key, fallback="[]"))
            return [Path(value) for value in values if isinstance(value, str)]
        except (json.JSONDecodeError, TypeError):
            return []

    @staticmethod
    def _deduplicate_paths(paths: list[Path], limit: int | None = None) -> list[Path]:
        result, seen = [], set()
        for path in paths:
            key = os.path.normcase(str(path))
            if key not in seen:
                seen.add(key); result.append(path)
            if limit is not None and len(result) >= limit:
                break
        return result

    def _record_recent(self, path: Path) -> None:
        self.recent_folders = self._deduplicate_paths([path, *self.recent_folders], 20)

    def _saved_paths(self, side: str) -> list[Path]:
        try:
            paths = json.loads(self.config_data.get(side, "tabs", fallback="[]"))
        except (json.JSONDecodeError, TypeError):
            paths = []
        candidates = [Path(value).expanduser() for value in paths]
        valid = [path for path in candidates if path.is_dir()]
        return valid or [Path.home()]

    def _restore_tab(self, tabs: PaneTabs, side: str) -> None:
        index = self.config_data.getint(side, "selected", fallback=0)
        if tabs.tabs():
            tabs.select(tabs.tabs()[min(max(index, 0), len(tabs.tabs()) - 1)])

    def _restore_panel_options(self, tabs: PaneTabs, side: str) -> None:
        column = self.config_data.get(side, "sort_column", fallback="name")
        descending = self.config_data.getboolean(side, "sort_descending", fallback=False)
        show_hidden = self.config_data.getboolean(side, "show_hidden", fallback=False)
        show_system = self.config_data.getboolean(side, "show_system", fallback=False)
        show_extensions = self.config_data.getboolean(side, "show_extensions", fallback=True)
        try:
            colors = json.loads(self.config_data.get(side, "tab_colors", fallback="[]"))
            locks = json.loads(self.config_data.get(side, "tab_locks", fallback="[]"))
            locked_paths = json.loads(self.config_data.get(side, "locked_paths", fallback="[]"))
            filters = json.loads(self.config_data.get(side, "tab_filters", fallback="[]"))
        except (json.JSONDecodeError, TypeError):
            colors, locks, locked_paths, filters = [], [], [], []
        for index, pane in enumerate(tabs.panes()):
            pane.sort_column = column if column in pane.all_sort_columns else "name"
            pane.reverse = descending
            pane.mix_sorting = self.mix_sorting_var.get()
            pane.show_hidden = show_hidden
            pane.show_system = show_system
            pane.show_extensions = show_extensions
            pane.set_quick_filter(filters[index] if index < len(filters) else "")
            color = colors[index] if index < len(colors) else self.get_tab_color(pane.path)
            tabs.set_color(pane, color, notify=False)
            mode = locks[index] if index < len(locks) else "unlocked"
            pane.lock_mode = mode if mode in {"unlocked", "locked", "reset"} else "unlocked"
            locked = Path(locked_paths[index]) if index < len(locked_paths) else pane.path
            pane.locked_path = locked if pane.lock_mode != "unlocked" and locked.is_dir() else None
            tabs.set_lock(pane, pane.lock_mode, notify=False)
            for col in pane.all_sort_columns:
                marker = (" ▼" if descending else " ▲") if col == pane.sort_column else ""
                pane.tree.heading("#0" if col == "name" else col, text=pane.heading_labels[col] + marker)
            pane.refresh()

    def _schedule_save(self, _event=None) -> None:
        if not self._ready:
            return
        if self._save_job is not None:
            self.after_cancel(self._save_job)
        self._save_job = self.after(250, self.save_config)

    def edit_home_prefixes(self):
        existing = getattr(self, "_prefix_preferences", None)
        if existing is not None and existing.winfo_exists():
            existing.lift()
            return
        self._prefix_preferences = PrefixPreferences(self, self.custom_home_prefixes, self.set_home_prefixes)

    def set_home_prefixes(self, items):
        self.custom_home_prefixes = items
        save_custom_prefixes(self.config_data, items)
        for pane in self.all_panes():
            pane.path_bar.redraw()
        self.save_config()

    def save_config(self, record_recent: bool = True) -> None:
        if not self._ready:
            return
        self._sync_single_workspace()
        ensure_config_defaults(self.config_data)
        if record_recent and self.active is not None:
            self._record_recent(self.active.persistent_path())
        for side, tabs in zip(PANEL_SECTIONS, self.panel_tabs):
            if not self.config_data.has_section(side):
                self.config_data.add_section(side)
            panes = tabs.panes()
            saved_paths = [
                p.persistent_path() if p.archive_session is not None
                else p.locked_path if p.lock_mode == "reset" and p.locked_path
                else p.persistent_path() for p in panes]
            self.config_data.set(side, "tabs", config_json([str(path) for path in saved_paths]))
            self.config_data.set(side, "tab_colors", json.dumps([
                tabs._colors.get(p, "default") for p in panes]))
            self.config_data.set(side, "tab_locks", json.dumps([p.lock_mode for p in panes]))
            self.config_data.set(side, "locked_paths", config_json([
                str(p.persistent_path() if p.archive_session is not None
                    else p.locked_path or p.persistent_path()) for p in panes]))
            self.config_data.set(side, "tab_filters", config_json([
                p.quick_filter_var.get() for p in panes], ensure_ascii=False))
            self.config_data.set(side, "selected", str(tabs.index(tabs.select())))
            current = tabs.current()
            self.config_data.set(side, "sort_column", current.sort_column)
            self.config_data.set(side, "sort_descending", str(current.reverse).lower())
            self.config_data.set(side, "show_hidden", str(current.show_hidden).lower())
            self.config_data.set(side, "show_system", str(current.show_system).lower())
            self.config_data.set(side, "show_extensions", str(current.show_extensions).lower())
        if not self.config_data.has_section("window"):
            self.config_data.add_section("window")
        if not self.config_data.has_section("state"):
            self.config_data.add_section("state")
        if not self.config_data.has_section("view"):
            self.config_data.add_section("view")
        if not self.config_data.has_section("refresh"):
            self.config_data.add_section("refresh")
        if not self.config_data.has_section("tab_colors"):
            self.config_data.add_section("tab_colors")
        if not self.config_data.has_section("startup"):
            self.config_data.add_section("startup")
        self.config_data.set("window", "geometry", self.geometry())
        active_tabs = self._tabs_for(self.active) if self.active is not None else self.panel_tabs[0]
        self.config_data.set("state", "active_panel", PANEL_SECTIONS[self.panel_tabs.index(active_tabs)])
        self.config_data.set("view", "font_size", self.font_size_var.get())
        self.config_data.set("view", "auto_font_size", str(self.auto_font_size_var.get()).lower())
        self.config_data.set("view", "right_click_menu", self.right_click_menu_var.get())
        self.config_data.set("view", "long_name_scrolling", str(self.long_name_scrolling_var.get()).lower())
        for c, variable in self.column_visible_vars.items():
            self.config_data.set('view', 'column_' + c, str(variable.get()).lower())
        for key, variable in (('date_order', self.date_order_var), ('time_style', self.time_style_var),
                              ('size_emphasis', self.size_emphasis_var), ('onedrive_overlay', self.onedrive_overlay_var),
                              ('vcs_overlay', self.vcs_overlay_var)):
            self.config_data.set('view', key, str(variable.get()))
        self.config_data.set("view", "tab_style", self.tab_style_var.get())
        self.config_data.set("view", "panel_count", str(self.panel_count_var.get()))
        self.config_data.set('view', 'multi_panel_count', str(self._multi_panel_count))
        self.config_data.set('view', 'folder_tree_ratio', str(self._tree_ratio))
        self.config_data.set('state', 'single_tab_order', json.dumps([
            (self.panel_tabs.index(self._tabs_for(p)), self._tabs_for(p).index(p))
            for p in self.single_tabs._tabs if p in self.all_panes()]))
        self.config_data.set("view", "ui_language", self.ui_language_var.get())
        self.config_data.set("view", "color_scheme", self.color_scheme_var.get())
        self.config_data.set("view", "extension_effect", str(self.extension_effect_var.get()).lower())
        self.config_data.set("view", "mix_sorting", str(self.mix_sorting_var.get()).lower())
        self.config_data.set("tab_colors", "colors", config_json(self._tab_colors, ensure_ascii=False))
        self.config_data.set("operations", "send_delete_to_recycle_bin", str(self.recycle_bin_var.get()).lower())
        self.config_data.set("operations", "continue_after_error", str(self.continue_errors_var.get()).lower())
        self.config_data.set("startup", "auto_start", str(self.auto_start_var.get()).lower())
        self.config_data.set("navigation", "favorites", config_json([str(path) for path in self.favorites], ensure_ascii=False))
        self.config_data.set("navigation", "recent_folders", config_json([str(path) for path in self.recent_folders], ensure_ascii=False))
        try:
            write_config_atomic(self.config_data, self.ini_path)
        except OSError as exc:
            self._show_config_save_warning(exc)

    def _show_config_save_warning(self, error: OSError) -> None:
        """Show one non-blocking warning when portable settings cannot be saved."""
        if self._config_warning_shown or not self.winfo_exists():
            return
        self._config_warning_shown = True
        warning = ttk.Label(self, text=tr("Settings could not be saved: {error}", error=error),
                            anchor="w", padding=(8, 4), style="Warning.TLabel")
        warning.pack(fill="x", before=self.split)
        self.after(10000, lambda: warning.destroy() if warning.winfo_exists() else None)

    def close_app(self) -> None:
        pending_sync = getattr(self, '_sync_dialog', None)
        if pending_sync is not None and pending_sync.winfo_exists():
            pending_sync.cancel()
            return
        if self.compare_window is not None and self.compare_window.winfo_exists():
            self.compare_window.close()
            if self.compare_window.winfo_exists(): return
        if self.preview_window is not None and self.preview_window.winfo_exists():
            self.preview_window.close()
        self._clear_tab_drag_target()
        if self._drag_state is not None:
            self._handle_internal_drag("cancel", self._drag_state["source"], None)
        if self._auto_refresh_job is not None:
            self.after_cancel(self._auto_refresh_job)
        self._directory_watches.close()
        if self._clipboard_job is not None:
            self.after_cancel(self._clipboard_job)
        if self._clipboard_resize_job is not None:
            self.after_cancel(self._clipboard_resize_job)
        if self._auto_font_job is not None:
            self.after_cancel(self._auto_font_job)
        if self._archive_open_poll_job is not None:
            self.after_cancel(self._archive_open_poll_job)
        if self._tray_poll_job is not None:
            self.after_cancel(self._tray_poll_job)
            self._tray_poll_job = None
        if self._tray_icon is not None:
            self._tray_icon.stop()
        for job in self._archive_open_jobs.values():
            job["cancel"].set()
            try:
                job["bar"].stop()
                job["progress"].destroy()
            except tk.TclError:
                pass
        if self.space_analyzer_window is not None and self.space_analyzer_window.winfo_exists():
            self.space_analyzer_window.close()
        self.save_config()
        for session in list(self._archive_sessions):
            self._close_archive_session(session, retries=0)
        self._archive_sessions.clear()
        self.destroy()

    def _sync_auto_start(self, show_error: bool = True) -> bool:
        if os.name != "nt":
            return False
        try:
            set_windows_autostart(self.auto_start_var.get())
        except OSError as exc:
            if show_error:
                messagebox.showerror(tr("Auto Start failed"), str(exc), parent=self)
            return False
        if self._tray_icon is not None:
            self._tray_icon.update(auto_start_enabled=self.auto_start_var.get())
        return True

    def toggle_auto_start(self) -> None:
        desired = self.auto_start_var.get()
        if not self._sync_auto_start():
            self.auto_start_var.set(not desired)
            return
        self.save_config()

    def _start_windows_tray(self) -> None:
        if os.name != "nt":
            return
        self._tray_icon = WindowsTrayIcon(
            self._tray_actions, pfc_icon_ico(32), open_label=tr("Open PFC"),
            auto_start_label=tr("Auto Start when boot"), exit_label=tr("Exit PFC"),
            auto_start_enabled=self.auto_start_var.get())
        self._tray_icon.start()
        self._tray_poll_job = self.after(100, self._poll_tray_actions)

    def _poll_tray_actions(self) -> None:
        self._tray_poll_job = None
        try:
            while True:
                action = self._tray_actions.get_nowait()
                if action == "show":
                    self.deiconify()
                    self.state("normal")
                    self.lift()
                    self.focus_force()
                elif action == "toggle_autostart":
                    self.auto_start_var.set(not self.auto_start_var.get())
                    self.toggle_auto_start()
                elif action == "exit":
                    self.close_app()
                    return
        except queue.Empty:
            pass
        if self.winfo_exists():
            self._tray_poll_job = self.after(100, self._poll_tray_actions)

    def _schedule_auto_refresh(self, delay=100) -> None:
        if not self.winfo_exists():
            return
        self._auto_refresh_job = self.after(max(50, delay), self._auto_refresh_tick)

    def _auto_refresh_tick(self) -> None:
        self._auto_refresh_job = None
        enabled = self.config_data.getboolean("refresh", "auto_refresh", fallback=True)
        panes = self.visible_panes()
        if self.cloud_status.roots:
            rows = self._visible_cloud_rows(panes)
            if self.onedrive_overlay_var.get():
                self.cloud_status.poll(path for pane, iid, path in rows)
            self._update_cloud_icons(rows)
        watch_paths = [pane.path for pane in panes
                       if enabled and pane.mode == "files" and pane.archive_session is None
                       and is_local_watch_path(pane.path)]
        watched = self._directory_watches.sync(watch_paths)
        if enabled:
            self._pending_directory_changes.update(self._directory_watches.drain())
            for key in tuple(self._pending_directory_changes):
                matching = [pane for pane in panes if directory_key(pane.path) == key]
                if any(pane._inline_editor is not None for pane in matching):
                    continue
                for pane in matching:
                    pane.refresh_if_changed()
                self._pending_directory_changes.discard(key)

            now = time.monotonic()
            # Network paths and failed/unsupported native watches keep their
            # configured polling fallback; local watched folders only receive
            # a low-frequency audit in case Windows overflowed an event buffer.
            for pane in panes:
                key = directory_key(pane.path)
                if key in watched:
                    continue
                interval = self.config_data.getint(
                    "refresh", "network_interval_ms" if str(pane.path).startswith("\\\\")
                    else "background_interval_ms", fallback=10000) / 1000
                if now >= self._network_refresh_due.get(key, 0):
                    pane.refresh_if_changed()
                    self._network_refresh_due[key] = now + max(1.0, interval)
            if now >= self._next_refresh_audit:
                for pane in panes:
                    if directory_key(pane.path) in watched:
                        pane.refresh_if_changed()
                self._next_refresh_audit = now + 30.0
        else:
            self._pending_directory_changes.clear()
        self._schedule_auto_refresh(100)

    def _visible_cloud_rows(self, panes):
        rows = []
        for pane in panes:
            if pane.archive_session is not None or pane._drag_press_item is not None:
                continue
            seen = set()
            for y in range(1, pane.tree.winfo_height(), 8):
                iid = pane.tree.identify_row(y)
                if not iid or iid in seen:
                    continue
                seen.add(iid)
                tags = pane.tree.item(iid, 'tags')
                if tags and tags[0] != 'PFC_INLINE_PLACEHOLDER':
                    rows.append((pane, iid, Path(tags[0])))
        return rows

    def _update_cloud_icons(self, rows):
        for pane, iid, path in rows:
            if pane._drag_press_item is None:
                icon = pane._icon(path, pane.tree.set(iid, 'size') == '<DIR>')
                if pane.tree.item(iid, 'image') != (str(icon),):
                    pane.tree.item(iid, image=icon)

    def _build_menu(self) -> None:
        previous_popup = getattr(self, "header_popup", None)
        if previous_popup is not None:
            previous_popup.close_all()
        previous_header = getattr(self, "header", None)
        if previous_header is not None and previous_header.winfo_exists():
            previous_header.destroy()
        menu_font = self._role_fonts['menu']
        header_bg = self.palette["header"]
        header_fg = self.palette["header_text"]
        active_bg = self.palette["header_active"]
        header = tk.Frame(self, background=header_bg, padx=5, pady=4)
        if hasattr(self, "split"):
            header.pack(fill="x", before=self.split)
        else:
            header.pack(fill="x")
        self.header = header
        # Pack the right-side summary first so Tk preserves it when horizontal
        # space is tight (especially in three/four-panel layouts).
        self.clipboard_summary_frame = tk.Frame(header, background=header_bg)
        self.clipboard_summary_frame.pack(side="right", padx=(12, 4))
        self.clipboard_summary_frame.pack_propagate(False)
        self.clipboard_icon_canvas = tk.Canvas(self.clipboard_summary_frame, width=52, height=24,
                                               highlightthickness=0, background=header_bg)
        self.clipboard_icon_canvas.pack(fill="both", expand=True)
        self.clipboard_summary = tk.Label(self.clipboard_summary_frame, text=tr("Clipboard: checking…"),
                                          anchor="e", width=1,
                                          font=self._role_fonts['auxiliary'],
                                          background=header_bg, foreground=self.palette["header_muted"])
        self.compare_target_label = tk.Label(
            header, text="", anchor="center", font=menu_font, padx=12, pady=2,
            background="#b8ef18", foreground="#c41421")
        self.compare_target_label.place(relx=.5, rely=.5, anchor="center")
        self.compare_target_tooltip = ToolTip(
            self.compare_target_label,
            lambda: (tr("Compare Target - {path}", path=str(self.compare_target))
                     if self.compare_target is not None else ""), delay=3000)
        header.bind("<Configure>", lambda _event: self._update_compare_target_label(), add="+")
        self._update_compare_target_label()
        title = tk.Label(header, text="PFC",
                         font=self._role_fonts['auxiliary'],
                         background=header_bg, foreground=header_fg, cursor="hand2")
        title.pack(side="left", padx=(2, 8))
        title.bind("<Button-1>", lambda _event: self.show_help())
        version_label = tk.Label(header, text=f"v{__version__}", font=self._role_fonts['auxiliary'],
                                 background=header_bg, foreground=self.palette["header_muted"])
        version_label.pack(side="left", padx=(0, 10))
        button_style = dict(font=menu_font, relief="flat", borderwidth=1, padx=8, pady=3,
                            cursor="hand2",
                            background=self.palette["header_button"], foreground=header_fg,
                            activebackground=active_bg, activeforeground="#ffffff")
        files_button = tk.Button(header, text=tr("Files"),
                                 command=lambda: self.show_header_menu("files"), **button_style)
        files_button.pack(side="left")
        files = tk.Menu(files_button, tearoff=False, font=menu_font,
                        postcommand=self._update_header_menu_states)
        files.add_command(label=tr("Open / Enter Folder"), accelerator="Enter",
                          command=self.enter_folder)
        files.add_command(label=tr("New Folder"), accelerator="F7", command=self.mkdir)
        files.add_separator()
        clipboard_menu = tk.Menu(files, tearoff=False, font=menu_font)
        clipboard_menu.add_command(label=tr("Copy to Clipboard"), accelerator="Ctrl+C",
                                   command=self.clipboard_copy)
        clipboard_menu.add_command(label=tr("Cut to Clipboard"), accelerator="Ctrl+X",
                                   command=self.clipboard_cut)
        clipboard_menu.add_command(label=tr("Paste"), accelerator="Ctrl+V",
                                   command=self.clipboard_paste)
        add_scaled_cascade(files, tr("Clipboard"), clipboard_menu)
        files.add_command(label=tr("Copy to Target Panel"), accelerator="F5", command=self.copy)
        files.add_command(label=tr("Move to Target Panel"), accelerator="F6", command=self.move)
        files.add_separator()
        files.add_command(label=tr("Rename"), accelerator="F2", command=self.rename)
        files.add_command(label=tr("Multi-Rename"), command=self.multi_rename)
        files.add_separator()
        files.add_command(label=tr("Delete"), accelerator="Del", command=self.delete)
        files.add_command(label=tr("Permanent Delete"), accelerator="Shift+Del", command=lambda: self.delete(permanent=True))
        operation_settings = tk.Menu(files, tearoff=False, font=menu_font)
        add_scaled_checkbutton(operation_settings, tr("Send Delete to Recycle Bin"),
                               self.recycle_bin_var, self.save_config)
        add_scaled_checkbutton(operation_settings, tr("Continue After File Errors"),
                               self.continue_errors_var, self.save_config)
        add_scaled_cascade(files, tr("File Operation Settings"), operation_settings)
        # Preserve the native model for contextual shortcuts, route preferences
        # through the consolidated dialog in the main menu.
        files.delete(files.index('end'))
        files.add_command(label=tr("File Operation Settings"), command=lambda:self.show_settings('navigation'))
        files.add_separator()
        files.add_command(label=tr("Exit"), command=self.close_app)
        align_scaled_cascade_arrows(files)

        go_button = tk.Button(header, text=tr("Go"),
                              command=lambda: self.show_header_menu("go"), **button_style)
